# --- 3. FUNCIONES DE APOYO Y SEGURIDAD ---
def make_columns_unique(df):
    if not isinstance(df, pd.DataFrame) or df.empty: return df
    cols = pd.Series(df.columns)
    for dup in cols[cols.duplicated()].unique():
        cols[cols == dup] = [f"{dup}_{i}" if i != 0 else dup for i in range(sum(cols == dup))]
    df.columns = cols
    return df

def parse_latam_number(val):
    if pd.isna(val): return 0.0
    if isinstance(val, (int, float)): return float(val)
    s = str(val).strip().replace(' ','').replace('$','')
    s = re.sub(r'[^\d.,-]','',s)
    if not s: return 0.0
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'): s = s.replace('.','').replace(',','.')
        else: s = s.replace(',','')
    elif ',' in s: s = s.replace(',','.')
    try: return float(s)
    except ValueError: return 0.0

def get_tipo_dia(fch):
    if fch is None: return "N/A"
    if fch in chile_holidays or fch.weekday() == 6: return "D/F"
    if fch.weekday() == 5: return "S"
    return "L"


# ===== v40 · PROMEDIOS ESTRICTAMENTE SEPARADOS POR JORNADA =====
# Los tres promedios usan SOLO fechas de su categoría chilena. La prioridad
# del feriado (incluido un sábado festivo) se define en get_tipo_dia.
_V40_JORNADAS = (('L', 'Laboral'), ('S', 'Sábado'), ('D/F', 'Domingo y festivo'))


def _v40_promedios(df, columna, fecha='Fecha', agrupacion='sum'):
    """Promedio de cada jornada, basado en una sola observación por fecha.

    agrupacion='sum': total diario por fecha antes de hacer promedio entre días.
    agrupacion='mean': promedio diario de filas de esa fecha; se usa para
    promedios de observaciones, mientras que el promedio de viajes THDR se
    calcula directamente por viaje y clase de jornada.
    No se inventan registros de fechas ausentes. No se suman fuentes distintas.
    """
    vacio = {nombre: {'valor': float('nan'), 'dias': 0} for _, nombre in _V40_JORNADAS}
    if (df is None or not isinstance(df, pd.DataFrame) or df.empty or
            fecha not in df or columna not in df):
        return vacio
    fechas = pd.to_datetime(df[fecha], errors='coerce').dt.normalize()
    valores = pd.to_numeric(df[columna], errors='coerce')
    z = pd.DataFrame({'_fecha': fechas, '_valor': valores}).dropna(subset=['_fecha', '_valor'])
    if z.empty:
        return vacio
    if agrupacion == 'sum':
        diario = z.groupby('_fecha', sort=False)['_valor'].sum(min_count=1)
    elif agrupacion == 'mean':
        diario = z.groupby('_fecha', sort=False)['_valor'].mean()
    else:
        raise ValueError('Agrupación de promedio no admitida')
    clases = pd.Series(diario.index.date, index=diario.index).map(get_tipo_dia)
    for codigo, nombre in _V40_JORNADAS:
        por_tipo = diario[clases.eq(codigo).values].dropna()
        if not por_tipo.empty:
            vacio[nombre] = {'valor': float(por_tipo.mean()), 'dias': int(len(por_tipo))}
    return vacio


def _v40_tarjetas(promedios, titulo='Promedio diario', unidad='', decimales=2):
    """Tres tarjetas fijas; para jornadas sin datos se muestra —, nunca cero."""
    tarjetas = st.columns(3)
    for (codigo, nombre), destino in zip(_V40_JORNADAS, tarjetas):
        r = promedios.get(nombre, {})
        v = r.get('valor', float('nan'))
        n = int(r.get('dias', 0))
        mostrado = (f'{_ncl(v, decimales)} {unidad}'.strip()
                    if pd.notna(v) and np.isfinite(v) else '—')
        _v36_tarjeta(destino, f'{titulo} · {nombre}', mostrado,
                     delta=f'{n} día(s) con dato' if n else 'Sin datos para esta jornada',
                     delta_color='off')


def _v40_desglose(df, columna, unidad='', titulo='Promedio diario',
                  fecha='Fecha', agrupacion='sum', decimales=2):
    promedios = _v40_promedios(df, columna, fecha, agrupacion)
    _v40_tarjetas(promedios, titulo=titulo, unidad=unidad, decimales=decimales)
    return promedios


def obtener_nombre_feriado(fch):
    if fch is None: return "No aplica"
    return chile_holidays.get(fch, "No es feriado")

def obtener_fecha_es(fecha):
    if pd.isna(fecha): return ""
    meses = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"]
    dias = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"]
    return f"{dias[fecha.weekday()]} {fecha.day} {meses[fecha.month - 1]} {fecha.year}"

# --- MOTOR DE EMPAREJAMIENTO DE ESTACIONES ---
def _norm(s):
    return str(s).upper().translate(str.maketrans("ÁÉÍÓÚÜÑ", "AEIOUUN"))

# Km acumulado de cada estación desde el origen (archivo "Km entre estaciones").
# Las distancias entre estaciones son simétricas entre Vía 1 y Vía 2, así que esta
# única tabla sirve para calcular el km recorrido de cualquier servicio (origen→destino).
_KM_ESTACION = {
    "PUERTO": 0.0, "BELLAVISTA": 0.72, "FRANCIA": 1.2, "BARON": 2.2, "PORTALES": 3.9,
    "RECREO": 6.0, "MIRAMAR": 7.4, "VINA DEL MAR": 8.3, "HOSPITAL": 9.55, "CHORRILLOS": 10.55,
    "EL SALTO": 11.71, "VALENCIA": 19.0, "QUILPUE": 21.43, "EL SOL": 23.3, "EL BELLOTO": 25.4,
    "AMERICAS": 26.4, "LAS AMERICAS": 26.4, "LA CONCEPCION": 27.6, "VILLA ALEMANA": 28.5,
    "SARGENTO ALDEA": 29.11, "PENABLANCA": 30.4, "LIMACHE": 43.13,
}
_LARGO_LINEA = 43.13  # Puerto–Limache, usado como respaldo si no se detecta el recorrido

def get_col_thdr(df, estacion, tipo):
    if df is None or df.empty: return None
    est_n = _norm(estacion)
    for c in df.columns:
        c_n = _norm(c)
        if not c_n.endswith("_MIN"): continue
        if 'PROGRAMADA' in c_n: continue
        
        if tipo == 'SALIDA' and 'SALIDA' not in c_n: continue
        if tipo == 'LLEGADA' and 'LLEGADA' not in c_n: continue
        
        if est_n in c_n: return c
        
        alias_map = {
            "VINA DEL MAR": ["VINA", "V. MAR", "V MAR", "VIÑA"],
            "EL BELLOTO": ["BELLOTO"],
            "LAS AMERICAS": ["AMERICAS"],
            "LA CONCEPCION": ["CONCEPCION"],
            "VILLA ALEMANA": ["VILLA", "ALEMANA", "V. ALEMANA"],
            "SARGENTO ALDEA": ["SARGENTO", "ALDEA", "S. ALDEA"],
            "PENABLANCA": ["PENA BLANCA", "PENABLANCA", "PEÑA BLANCA"],
            "EL SALTO": ["SALTO"]
        }
        if est_n in alias_map:
            for alias in alias_map[est_n]:
                if alias in c_n: return c
    return None

def _srv_clean_series(s):
    # Limpia el número de servicio de forma robusta: usa el valor numérico tal cual
    # (evita que floats como 1.0 se vuelvan "10" al quitar el punto) y solo extrae
    # dígitos como respaldo para textos tipo 'V123'.
    num = pd.to_numeric(s, errors='coerce')
    if num.isna().any():
        resto = pd.to_numeric(pd.Series(s).astype(str).str.replace(r'\D', '', regex=True), errors='coerce')
        num = num.fillna(resto)
    return num

def clasificar_od_thdr(df_thdr):
    # Clasifica cada servicio por su recorrido real: el ORIGEN es la estación donde está la
    # PRIMERA hora del viaje y el DESTINO la estación donde está la ÚLTIMA hora (sea de
    # llegada o de salida, la que el THDR registre). No se usa el número de servicio ni el
    # orden geográfico: así un 4xx que parte de Limache queda LI-PU y un 6xx que parte de
    # Sargento Aldea queda SA-PU.
    if df_thdr is None or df_thdr.empty:
        return pd.Series(dtype=object)
    sal = pd.DataFrame(index=df_thdr.index)
    lle = pd.DataFrame(index=df_thdr.index)
    for est in ESTACIONES:
        cs = get_col_thdr(df_thdr, est, 'SALIDA')
        cl = get_col_thdr(df_thdr, est, 'LLEGADA')
        sal[est] = pd.to_numeric(df_thdr[cs], errors='coerce') if cs else np.nan
        lle[est] = pd.to_numeric(df_thdr[cl], errors='coerce') if cl else np.nan
    def _od(i):
        s = sal.loc[i]; l = lle.loc[i]
        # Horas de paso por cada estación (llegada y/o salida, las que existan).
        _paso = {}
        for e in ESTACIONES:
            _hh = [h for h in (s[e], l[e]) if pd.notna(h)]
            if _hh:
                _paso[e] = _hh
        if len(_paso) < 2:
            return pd.NA
        # Si el viaje cruza medianoche, las horas bajas son del día siguiente: se corrigen.
        _todas = [h for _v in _paso.values() for h in _v]
        if max(_todas) - min(_todas) > 720:
            _paso = {e: [h + 1440 if h < 720 else h for h in _v] for e, _v in _paso.items()}
        # Regla general: el ORIGEN es la estación recorrida primero en el tiempo y el
        # DESTINO la última. No depende del número de servicio ni del orden geográfico,
        # así un 4xx que parte de Limache queda LI-PU y un 6xx que parte de Sgto. Aldea
        # queda SA-PU, y el kilometraje sale de ese recorrido real.
        o = min(_paso, key=lambda e: min(_paso[e]))
        d = max(_paso, key=lambda e: max(_paso[e]))
        if o == d:
            return pd.NA
        return f"{SHORT_NAMES_DICT.get(o, o)}→{SHORT_NAMES_DICT.get(d, d)}"
    return df_thdr.index.to_series().apply(_od)

