# Sin @st.cache_data a propósito: con parámetros "_" Streamlit no los usa como clave y devolvía siempre el 1er archivo. El caché en disco ya distingue cada archivo.
def _seat_cache(_nombre, _bytes, _sd, _ed):
    """Procesa SEAT (energía diaria) y SAF LI con Parquet en disco. Devuelve (all_seat, all_saf_li, error)."""
    _key = _hash_bytes(_bytes, _nombre, _sd, _ed, _PARSE_VERSION)
    _ps = os.path.join(_CACHE_DIR, f"seat_{_key}_seat.parquet")
    _pl = os.path.join(_CACHE_DIR, f"seat_{_key}_saf.parquet")
    if os.path.exists(_ps) and os.path.exists(_pl):
        try:
            return (pd.read_parquet(_ps).to_dict('records'), pd.read_parquet(_pl).to_dict('records'), None)
        except Exception:
            pass
    _seat = []; _saf = []
    try:
        _es = "xlrd" if _nombre.lower().endswith(".xls") else "openpyxl"
        _sa_y, _sa_m = _mes_archivo(_nombre)
        _ds = pd.read_excel(BytesIO(_bytes), header=None, engine=_es)
        _fs = pd.to_datetime(_ds.iloc[:, 1], errors='coerce')
        _dts = _fs.dt.date
        _msk = _fs.notna() & (_dts >= _sd) & (_dts <= _ed)
        if _msk.any():
            _sdf = pd.DataFrame({
                'Fecha': _fs[_msk].dt.normalize().values,
                'E_Total': _ds.loc[_msk, 3].map(parse_latam_number).values,
                'E_Tr': _ds.loc[_msk, 5].map(parse_latam_number).values,
                'E_12': _ds.loc[_msk, 7].map(parse_latam_number).values})
            _sdf['_arch'] = _nombre; _sdf['_arch_anio'] = _sa_y; _sdf['_arch_mes'] = _sa_m
            _seat = _sdf.to_dict('records')
        # Hoja SAFs: Limache (Taller=col6, TGSN=col7) — vectorizado
        try:
            _xs = pd.ExcelFile(BytesIO(_bytes), engine=_es)
            _hsaf = next((s for s in _xs.sheet_names if 'saf' in s.lower()), None)
            if _hsaf:
                _dsaf = pd.read_excel(BytesIO(_bytes), sheet_name=_hsaf, header=None, engine=_es)
                _fl = pd.to_datetime(_dsaf.iloc[:, 1], errors='coerce')
                _dl = _fl.dt.date
                _mk = _fl.notna() & (_dl >= _sd) & (_dl <= _ed)
                if _mk.any():
                    _tal = _dsaf.loc[_mk, 6].map(parse_latam_number)
                    _tg = _dsaf.loc[_mk, 7].map(parse_latam_number)
                    _ldf = pd.DataFrame({'Fecha': _fl[_mk].dt.normalize().values, 'SAF_Taller': _tal.values, 'SAF_TGSN': _tg.values})
                    _ldf = _ldf[(_ldf['SAF_Taller'] > 0) | (_ldf['SAF_TGSN'] > 0)]
                    _saf = _ldf.to_dict('records')
        except Exception:
            pass
    except Exception as _e:
        return _seat, _saf, f"SEAT: {_e}"
    try:
        pd.DataFrame(_seat).to_parquet(_ps, index=False)
        pd.DataFrame(_saf).to_parquet(_pl, index=False)
    except Exception:
        pass
    return _seat, _saf, None


# Sin @st.cache_data a propósito: con parámetros "_" Streamlit no los usa como clave y devolvía siempre el 1er archivo. El caché en disco ya distingue cada archivo.
def _umr_cache(_nombre, _bytes, _sd, _ed):
    """Procesa el UMR (odómetro, km por tren, KM-Servicio) con Parquet en disco.
    Devuelve (all_ops, all_tr, all_kmserv, error)."""
    _key = _hash_bytes(_bytes, _nombre, _sd, _ed, _PARSE_VERSION)
    _po = os.path.join(_CACHE_DIR, f"umr_{_key}_ops.parquet")
    _pt = os.path.join(_CACHE_DIR, f"umr_{_key}_tr.parquet")
    _pk = os.path.join(_CACHE_DIR, f"umr_{_key}_kms.parquet")
    if os.path.exists(_po) and os.path.exists(_pt) and os.path.exists(_pk):
        try:
            return (pd.read_parquet(_po).to_dict('records'),
                    pd.read_parquet(_pt).to_dict('records'),
                    pd.read_parquet(_pk).to_dict('records'), None)
        except Exception:
            pass
    _ops = []; _tr = []; _kms = []
    try:
        _eu = "xlrd" if _nombre.lower().endswith(".xls") else "openpyxl"
        _xl = pd.ExcelFile(BytesIO(_bytes), engine=_eu)
        for _sn in _xl.sheet_names:
            _raw = pd.read_excel(BytesIO(_bytes), sheet_name=_sn, header=None, engine=_eu)
            _hr = next((i for i in range(min(100, len(_raw))) if any(k in str(_raw.iloc[i].tolist()).upper() for k in ['FECHA', 'ODO', 'KILOM'])), None)
            if _hr is not None:
                _dp = pd.read_excel(BytesIO(_bytes), sheet_name=_sn, header=_hr, engine=_eu)
                _dp.columns = [str(c).upper().replace('Ó', 'O').strip() for c in _dp.columns]
                _cf = next((c for c in _dp.columns if 'FECHA' in c), None)
                _co = next((c for c in _dp.columns if 'ODO' in c), None)
                _ct = next((c for c in _dp.columns if 'KM' in c), None)
                if _cf and _co:
                    _dt = pd.to_datetime(_dp[_cf], errors='coerce').dt.normalize()
                    _msk = (_dt.dt.date >= _sd) & (_dt.dt.date <= _ed) & _dt.notna()
                    _dv = _dp[_msk]
                    if not _dv.empty:
                        _od_v = _dv[_co].map(parse_latam_number)
                        _tk_v = _dv[_ct].map(parse_latam_number) if _ct else pd.Series(0.0, index=_dv.index)
                        _tmp = pd.DataFrame({
                            'Fecha': _dt[_msk].values,
                            'Tipo Día': _dt[_msk].dt.date.map(get_tipo_dia).values,
                            'Odómetro [km]': _od_v.values,
                            'Tren-Km [km]': _tk_v.values})
                        _ops.extend(_tmp.to_dict('records'))
            if any(k in _sn.upper() for k in ['KIL', 'ODO']):
                _clase = None; _fcols = {}
                for i in range(len(_raw)):
                    _txt = ' '.join(str(x).upper() for x in _raw.iloc[i].tolist()[:4] if pd.notna(x))
                    if 'DIARIO' in _txt:
                        _clase = 'km'
                    elif ('OD' in _txt and 'METR' in _txt) or 'ODOMETR' in _txt:
                        _clase = 'odo'
                    _ff = {}
                    for j in range(1, len(_raw.columns)):
                        _vf = pd.to_datetime(_raw.iloc[i, j], errors='coerce')
                        if pd.notna(_vf) and 2020 <= _vf.year <= 2035:
                            _ff[j] = _vf
                    if len(_ff) >= 3:
                        _fcols = _ff
                    _t = str(_raw.iloc[i, 0]).strip().upper()
                    if re.match(r'^4\d{2}(\.0+)?$', _t):
                        _t = f"SFE {int(float(_t))}"
                    _msfe = re.match(r'^SFE[\s\-_.]*0*(\d+)$', _t)
                    if _msfe:
                        _t = f"SFE {int(_msfe.group(1))}"
                    if _clase and _fcols and re.match(r'^(M|XM|SFE)', _t):
                        for j, _fe in _fcols.items():
                            if _sd <= _fe.date() <= _ed:
                                _tr.append({"Tren": _t, "Fecha": _fe.normalize(),
                                            "Valor": parse_latam_number(_raw.iloc[i, j]), "Clase": _clase})
            if 'SERV' in _sn.upper() and 'KM' in _sn.upper():
                _fe_kms = pd.to_datetime(_raw.iloc[4:, 0], errors='coerce').ffill()
                for _ri in range(4, len(_raw)):
                    _od = _raw.iloc[_ri, 5]
                    _fe = _fe_kms.get(_ri)
                    if pd.notna(_od) and pd.notna(_fe) and re.match(r'^[A-Z]{2,3}-[A-Z]{2,3}$', str(_od).strip().upper()) and _sd <= _fe.date() <= _ed:
                        _kms.append({"Fecha": _fe.normalize(), "OD": str(_od).strip().upper(),
                                     "KmsxTrenes": parse_latam_number(_raw.iloc[_ri, 9]),
                                     "KmTrenR": parse_latam_number(_raw.iloc[_ri, 22]),
                                     "KmTrenP": parse_latam_number(_raw.iloc[_ri, 23]),
                                     "SimP": parse_latam_number(_raw.iloc[_ri, 1]),
                                     "DobP": parse_latam_number(_raw.iloc[_ri, 2]),
                                     "SimR": parse_latam_number(_raw.iloc[_ri, 3]),
                                     "DobR": parse_latam_number(_raw.iloc[_ri, 4]),
                                     "Cortes_EB": parse_latam_number(_raw.iloc[_ri, 16]),
                                     "Cortes_SA": parse_latam_number(_raw.iloc[_ri, 17]),
                                     "Cortes_PE": parse_latam_number(_raw.iloc[_ri, 18]),
                                     "Acoples_EB": parse_latam_number(_raw.iloc[_ri, 19]),
                                     "Acoples_SA": parse_latam_number(_raw.iloc[_ri, 20]),
                                     "Acoples_PE": parse_latam_number(_raw.iloc[_ri, 21])})
    except Exception as _e:
        return _ops, _tr, _kms, f"UMR: {_e}"
    try:
        pd.DataFrame(_ops).to_parquet(_po, index=False)
        pd.DataFrame(_tr).to_parquet(_pt, index=False)
        pd.DataFrame(_kms).to_parquet(_pk, index=False)
    except Exception:
        pass
    return _ops, _tr, _kms, None


# ===== Lector general de Factura y PRMTE =====
# No depende del nombre de la hoja, de la fila del encabezado ni de cómo venga escrita la fecha:
# - reconoce las columnas por su contenido, sin tildes ni caracteres invisibles ('DÍA' = 'DIA', 'Hoja1' = 'Consumo Factura');
# - lee fechas de Excel, números de serie o texto (día-mes-año; mes-día-año solo si calza mejor con el PRMTE);
# - pasa a hora local una factura armada en hora UTC (lo detecta comparándola con el PRMTE del mismo archivo);
# - no usa filas de factura fuera del período del PRMTE del archivo;
# - deja una ficha por archivo con lo que leyó, lo que ajustó y lo que falta (pestaña Energía).
import json as _json
import warnings as _warnings
import unicodedata as _ud
_BOM = chr(0xFEFF)
_H_MIN_DIA = 22  # horas con energía (de 24) para dar por completo un día de Factura o PRMTE
_TOK_HDR = ('FECHA', 'ANO', 'YEAR', 'MES', 'DIA', 'HORA', 'CONSUMO', 'FACTURA', 'RETIRO', 'ENERGIA', 'KWH')


def _txt_norm(_v):
    """Texto sin tildes ni caracteres invisibles y en mayúsculas: 'Día ' → 'DIA', 'AÑO' → 'ANO'."""
    _s = _ud.normalize('NFKD', str(_v).replace(_BOM, '')).encode('ascii', 'ignore').decode()
    return re.sub(r'\s+', ' ', _s).strip().upper()


def _num_txt(_s):
    """Números aunque vengan como texto o con caracteres invisibles."""
    return pd.to_numeric(pd.Series(_s).astype(str).str.replace(_BOM, '', regex=False).str.strip(), errors='coerce')


def _fechas_generales(_s, _ref=None):
    """Fecha-hora venga como venga: fecha de Excel, número de serie o texto. El texto tipo 2026-06-01 se lee tal cual;
    el resto (01-06-26) se lee día-mes-año, salvo que mes-día-año calce mejor con el período _ref = (inicio, fin).
    Devuelve (fechas, cómo se leyó el texto)."""
    _s = pd.Series(_s).reset_index(drop=True)
    _out = pd.Series(pd.NaT, index=_s.index, dtype='datetime64[ns]')
    _es_f = _s.map(lambda _v: isinstance(_v, (datetime, date)))
    if _es_f.any():
        _out[_es_f] = pd.to_datetime(_s[_es_f], errors='coerce')
    _n = pd.to_numeric(_s.where(~_es_f), errors='coerce')
    _es_n = _n.between(20000, 80000)  # número de serie de Excel
    if _es_n.any():
        _out[_es_n] = pd.Timestamp('1899-12-30') + pd.to_timedelta(_n[_es_n], unit='D')
    _t = _s.astype(str).str.replace(_BOM, '', regex=False).str.strip()
    _t = _t.where(_s.notna() & ~_es_f & ~_es_n & (_t != ''))
    _modo = ''
    with _warnings.catch_warnings():
        _warnings.simplefilter('ignore')
        _iso = _t.str.match(r'^\d{4}[-/.]\d{1,2}[-/.]\d{1,2}', na=False)
        if _iso.any():
            _out[_iso] = pd.to_datetime(_t[_iso], errors='coerce', format='mixed')
        _otro = _t.notna() & ~_iso
        if _otro.any():
            _a = pd.to_datetime(_t[_otro], errors='coerce', dayfirst=True, format='mixed')
            _b = pd.to_datetime(_t[_otro], errors='coerce', dayfirst=False, format='mixed')
            if _ref is not None:
                _pa, _pb = int(_a.between(*_ref).sum()), int(_b.between(*_ref).sum())
            else:
                _pa, _pb = -_a.dt.to_period('M').nunique(), -_b.dt.to_period('M').nunique()
            _usa_b = _pb > _pa
            _out[_otro] = _b if _usa_b else _a
            if _out[_otro].notna().any():
                _modo = 'fecha en texto mes-día-año' if _usa_b else 'fecha en texto día-mes-año'
    return _out.dt.round('s'), _modo  # al segundo: el número de serie de Excel trae decimales (00:59:59,999 → 01:00)


def _tabla_energia(_raw, _ref=None):
    """De una hoja leída sin encabezado arma (tabla ts/Consumo, tipo, notas). Tipo 'PRMTE' si trae columnas de
    retiro de energía activa; si no, 'Factura'. None si la hoja no tiene fecha y consumo."""
    _raw = _raw.dropna(how='all').dropna(axis=1, how='all').reset_index(drop=True)
    if _raw.shape[0] < 2 or _raw.shape[1] < 2:
        return None
    _h = next((_i for _i in range(min(30, len(_raw)))
               if sum(any(_k in _txt_norm(_v) for _k in _TOK_HDR) for _v in _raw.iloc[_i].tolist() if pd.notna(_v)) >= 2), None)
    if _h is not None:
        _nom = [_txt_norm(_v) if pd.notna(_v) else '' for _v in _raw.iloc[_h].tolist()]
        _d = _raw.iloc[_h + 1:].reset_index(drop=True)
    else:  # sin encabezado: la columna con más fechas es la fecha
        _cnt = [int(_raw[_c].map(lambda _v: isinstance(_v, (datetime, date))).sum()) for _c in _raw.columns]
        if max(_cnt) < 24:
            return None
        _nom = ['FECHA' if _j == int(np.argmax(_cnt)) else '' for _j in range(_raw.shape[1])]
        _d = _raw.reset_index(drop=True)
    _d.columns = range(_d.shape[1])
    _col = lambda _f: next((_j for _j, _n in enumerate(_nom) if _n and _f(_n)), None)
    _cA = _col(lambda _n: _n.startswith('ANO') or _n == 'YEAR')
    _cM = _col(lambda _n: _n.startswith('MES') or _n == 'MONTH')
    _cD = _col(lambda _n: _n.startswith('DIA') or _n == 'DAY')
    _cH = _col(lambda _n: _n.startswith('HORA') and 'UTC' not in _n)
    _cU = _col(lambda _n: _n.startswith('HORA') and 'UTC' in _n)
    _cI = _col(lambda _n: 'INICIO' in _n or _n.startswith('MINUTO'))
    _cF = _col(lambda _n: 'FECHA' in _n)
    _ret = [_j for _j, _n in enumerate(_nom) if 'RETIRO' in _n and 'ACTIVA' in _n and 'REACTIVA' not in _n]
    _notas, _lbl_utc = [], None
    if _cA is not None and _cM is not None and _cD is not None:
        # Fecha armada con año/mes/día/hora/minuto (PRMTE)
        _y, _m, _dd = _num_txt(_d[_cA]), _num_txt(_d[_cM]), _num_txt(_d[_cD])
        _mi = _num_txt(_d[_cI]).fillna(0) if _cI is not None else 0
        _hc = _cH if _cH is not None else _cU
        _hh = _num_txt(_d[_hc]) if _hc is not None else pd.Series(0, index=_d.index)
        _ts = pd.to_datetime(dict(year=_y, month=_m, day=_dd, hour=_hh, minute=_mi), errors='coerce')
        if _cH is None and _cU is not None:
            _notas.append('solo trae hora UTC')
        if _cH is not None and _cU is not None:  # "día local + hora UTC": para detectar una factura armada en hora UTC
            _lbl_utc = pd.to_datetime(dict(year=_y, month=_m, day=_dd, hour=_num_txt(_d[_cU])), errors='coerce')
    elif _cF is not None:
        _ts, _modo = _fechas_generales(_d[_cF], _ref)
        if _modo:
            _notas.append(_modo)
        if _cH is not None and len(_ts.dropna()) and (_ts.dropna().dt.hour == 0).all():
            # Fecha y hora en columnas separadas (hora 1..24 = hora que termina)
            _hh = _num_txt(_d[_cH])
            if _hh.isna().all():
                _hh = pd.to_datetime(_d[_cH].astype(str), errors='coerce', format='mixed').dt.hour
            if _hh.min() >= 1 and _hh.max() == 24:
                _hh = _hh - 1
            _ts = _ts + pd.to_timedelta(_hh.fillna(0), unit='h')
    else:
        return None
    if _ret:
        _tipo = 'PRMTE'
        _v = sum(_d[_j].map(parse_latam_number) for _j in _ret)
    else:
        _tipo = 'Factura'
        _usadas = {_cF, _cA, _cM, _cD, _cH, _cU, _cI}
        _jv = _col(lambda _n: 'FECHA' not in _n and (_n.startswith('EA ') or any(_k in _n for _k in ('FACTURA', 'CONSUMO', 'KWH', 'ENERGIA', 'VALOR'))))
        if _jv is None:
            _cand = [_j for _j in range(_d.shape[1]) if _j not in _usadas]
            _jv = max(_cand, key=lambda _j: int(_num_txt(_d[_j]).notna().sum()), default=None)
        if _jv is None:
            return None
        _v = _d[_jv].map(parse_latam_number).abs()
    _ok = _ts.notna()
    if int(_ok.sum()) < 4:
        return None
    _t = pd.DataFrame({'ts': _ts[_ok].values, 'Consumo': pd.Series(_v, index=_d.index)[_ok].values})
    if _lbl_utc is not None:
        _t['lbl_utc'] = _lbl_utc[_ok].values
    return _t, _tipo, _notas


def _dias_cortados(_t):
    """Días cortados en los bordes del archivo (bajado antes de terminar el día o el mes, o empezado tarde): los días
    sin energía al inicio o al final, y el primer o último día con energía si trae menos de _H_MIN_DIA horas.
    Un día del medio con horas en cero (p. ej. el apagón del 25-02-2025) es dato real y se usa."""
    if _t is None or _t.empty:
        return []
    _dias = pd.date_range(_t['ts'].min().normalize(), _t['ts'].max().normalize())
    _p = _t[_t['Consumo'] > 0]
    if _p.empty:
        return list(_dias)
    _h = _p.groupby(_p['ts'].dt.normalize())['ts'].apply(lambda _s: _s.dt.hour.nunique()).reindex(_dias, fill_value=0)
    _con = _h[_h > 0].index
    _cort = [_f for _f in _dias if _f < _con.min() or _f > _con.max()]
    _cort += [_f for _f in {_con.min(), _con.max()} if _h[_f] < _H_MIN_DIA]
    return sorted(_cort)


# Sin @st.cache_data a propósito: con parámetros "_" Streamlit no los usa como clave y devolvía siempre el 1er archivo. El caché en disco ya distingue cada archivo.
def _bill_cache(_nombre, _bytes, _sd, _ed):
    """Factura y PRMTE de un archivo con el lector general. Devuelve (factura, prmte_rango, prmte_2025, error, ficha).
    Se guarda en Parquet en disco para no reprocesar."""
    _key = _hash_bytes(_bytes, _nombre, _sd, _ed, _PARSE_VERSION, "lector-general-1")
    _pf, _pp, _p25, _pj = [os.path.join(_CACHE_DIR, f"bill_{_key}_{_s}") for _s in ("fact.parquet", "prmte.parquet", "prmte25.parquet", "ficha.json")]
    if all(os.path.exists(_x) for _x in (_pf, _pp, _p25, _pj)):
        try:
            with open(_pj, encoding='utf-8') as _fh:
                _ficha = _json.load(_fh)
            return (pd.read_parquet(_pf).to_dict('records'), pd.read_parquet(_pp).to_dict('records'),
                    pd.read_parquet(_p25).to_dict('records'), None, _ficha)
        except Exception:
            pass  # caché corrupto: reprocesa
    _fact, _prmte, _prmte25 = [], [], []
    _ficha = {'Archivo': _nombre, 'Factura': '—', 'PRMTE': '—', 'Ajustes automáticos': '', 'Avisos': ''}
    _aj, _av = [], []
    _dm = lambda _x: pd.Timestamp(_x).strftime('%d-%m-%y')
    try:
        _eb = "xlrd" if _nombre.lower().endswith(".xls") else "openpyxl"
        _hojas = pd.read_excel(BytesIO(_bytes), sheet_name=None, header=None, engine=_eb)
        # 1) Se clasifica cada hoja por su contenido. El PRMTE va primero: su período sirve para leer bien la factura.
        _tp, _hf, _vacias = None, [], []
        for _sn, _raw in _hojas.items():
            _r = _tabla_energia(_raw)
            if _r is None:
                if 'PRMTE' not in _sn.upper():
                    _vacias.append(_sn)
                continue
            if _r[1] == 'PRMTE':
                if _tp is None or len(_r[0]) > len(_tp[0]):
                    _tp = _r
            else:
                _hf.append(_sn)
        _ref, _p_loc = None, None
        if _tp is not None:
            _dfp = _tp[0]
            _aj.extend(_tp[2])
            _ref = (_dfp['ts'].min().normalize() - pd.Timedelta(days=1), _dfp['ts'].max().normalize() + pd.Timedelta(days=2))
            _p_loc = _dfp.groupby(_dfp['ts'].dt.floor('h'))['Consumo'].sum()
            _ficha['PRMTE'] = f"{_ncl(len(_dfp), 0)} reg. 15 min · {_dm(_dfp['ts'].min())} → {_dm(_dfp['ts'].max())} · {_ncl(_dfp['Consumo'].sum(), 0)} kWh"
            _cort = _dias_cortados(_dfp)
            if _cort:  # un día cortado no sirve como total del día: no se usa (manda la fuente siguiente)
                _av.append("PRMTE cortado, no se usa: " + ", ".join(_q.strftime('%d-%m') for _q in _cort[:6]) + ("…" if len(_cort) > 6 else ""))
                _dfp = _dfp[~_dfp['ts'].dt.normalize().isin(_cort)]
            _pr = pd.DataFrame({'Fecha': _dfp['ts'].dt.normalize(), 'Hora': _dfp['ts'].dt.strftime('%H:00'),
                                '15min': _dfp['ts'].dt.strftime('%H:%M'), 'Consumo': _dfp['Consumo']})
            _dd = _dfp['ts'].dt.date
            _prmte = _pr[((_dd >= _sd) & (_dd <= _ed)).values].to_dict('records')
            _prmte25 = _pr[(_dfp['ts'].dt.year == 2025).values].to_dict('records')
        # 2) Factura: la hoja con más filas de fecha y consumo, leída con el período del PRMTE como referencia
        _tf = None
        for _sn in _hf:
            _r = _tabla_energia(_hojas[_sn], _ref)
            if _r is not None and (_tf is None or len(_r[0]) > len(_tf[0][0])):
                _tf = (_r, _sn)
        if _tf is not None:
            (_f, _tipo_f, _nf), _snf = _tf
            _aj.extend(_nf)
            # Factura armada con la hora UTC del PRMTE: calza con el PRMTE solo en hora UTC → se pasa a hora local
            if _tp is not None and 'lbl_utc' in _tp[0].columns:
                _dfp = _tp[0]
                _p_utc = _dfp.groupby('lbl_utc')['Consumo'].sum()
                _h0 = _f['ts'].dt.floor('h')
                _fh = _f.groupby(_h0)['Consumo'].sum()
                _e_loc = (_fh - _p_loc.reindex(_fh.index)).abs().mean()
                _e_utc = (_fh - _p_utc.reindex(_fh.index)).abs().mean()
                if pd.notna(_e_utc) and pd.notna(_e_loc) and _e_utc < 0.2 * _e_loc:
                    _mapa = pd.Series(_dfp['ts'].dt.floor('h').values, index=_dfp['lbl_utc'].values)
                    _mapa = _mapa[~_mapa.index.duplicated()]
                    _f = _f.assign(ts=_h0.map(_mapa) + (_f['ts'] - _h0)).dropna(subset=['ts'])
                    _aj.append('factura en hora UTC → hora local')
            if _ref is not None:
                _fuera = ~_f['ts'].between(*_ref)
                if _fuera.any():
                    _av.append(f"{int(_fuera.sum())} filas de factura fuera del período del PRMTE (no se usan)")
                    _f = _f[~_fuera]
            _cort = _dias_cortados(_f)
            if _cort:
                _av.append("factura cortada, no se usa: " + ", ".join(_q.strftime('%d-%m') for _q in _cort[:6]) + ("…" if len(_cort) > 6 else ""))
            if not _f.empty:
                _ficha['Factura'] = f"«{_snf}» · {_f['ts'].dt.floor('h').nunique()} h · {_dm(_f['ts'].min())} → {_dm(_f['ts'].max())} · {_ncl(_f['Consumo'].sum(), 0)} kWh"
                _f = _f[~_f['ts'].dt.normalize().isin(_cort)]
            if not _f.empty:
                _dt = pd.to_datetime(_f['ts'])
                _fact = pd.DataFrame({'Fecha': _dt.dt.normalize().values, 'Hora': _dt.dt.strftime('%H:00').values,
                                      '15min': (_dt.dt.strftime('%H:') + (_dt.dt.minute // 15 * 15).map(lambda _m: f"{_m:02d}")).values,
                                      'Consumo': _f['Consumo'].values}).to_dict('records')
                if _p_loc is not None:
                    _fh = _f.groupby(_f['ts'].dt.floor('h'))['Consumo'].sum()
                    _com = _fh.index.intersection(_p_loc.index)
                    if len(_com) >= 24 and _p_loc[_com].sum() > 0:
                        _dif = (_fh[_com].sum() / _p_loc[_com].sum() - 1) * 100
                        if abs(_dif) > 2:
                            _av.append(f"factura y PRMTE difieren {_ncl(_dif, 1)} % en las mismas horas")
        elif _vacias:
            _ficha['Factura'] = "— (hoja " + ", ".join(f"«{_s}»" for _s in _vacias) + " sin datos)"
        else:
            _ficha['Factura'] = "— (no trae)"
        if _tp is None:
            _av.append("no se encontró PRMTE")
    except Exception as _e:
        _ficha['Avisos'] = f"no se pudo leer: {_e}"
        return _fact, _prmte, _prmte25, f"Factura/PRMTE: {_e}", _ficha
    _ficha['Ajustes automáticos'] = "; ".join(dict.fromkeys(_aj))
    _ficha['Avisos'] = "; ".join(_av)
    # Guardar en Parquet para las próximas cargas (y tras reinicios del servidor)
    try:
        pd.DataFrame(_fact).to_parquet(_pf, index=False)
        pd.DataFrame(_prmte).to_parquet(_pp, index=False)
        pd.DataFrame(_prmte25).to_parquet(_p25, index=False)
        with open(_pj, 'w', encoding='utf-8') as _fh:
            _json.dump(_ficha, _fh, ensure_ascii=False)
    except Exception:
        pass
    return _fact, _prmte, _prmte25, None, _ficha


def _unir_por_fecha(_listas):
    """Junta los registros de varios archivos sin duplicar días: si un día viene en más de un archivo
    (copias, meses que se traslapan), se usa el que trae más horas con energía ese día."""
    _dfs = [pd.DataFrame(_l).assign(_arch=_i) for _i, _l in enumerate(_listas) if _l]
    if not _dfs:
        return []
    _d = pd.concat(_dfs, ignore_index=True)
    if _d['_arch'].nunique() > 1:
        _d['Fecha'] = pd.to_datetime(_d['Fecha']).dt.normalize()
        _n = (_d[pd.to_numeric(_d['Consumo'], errors='coerce') > 0].groupby(['Fecha', '_arch'])['Hora'].nunique().rename('_n')
              .reset_index().sort_values(['Fecha', '_n', '_arch'], ascending=[True, False, True]).drop_duplicates('Fecha'))
        _d = _d.merge(_n[['Fecha', '_arch']], on=['Fecha', '_arch'])
    return _d.drop(columns='_arch').to_dict('records')


def procesar_viajes_contrato(f, start_date, end_date):
    """Lee archivos 'Viajes por Contrato' (resumen mensual por tipo de tarifa).
    Col 0 = fecha (yyyy/mm/dd), columnas siguientes = viajes por tarifa.
    Devuelve df con Fecha y 'Total Viajes' por día (suma de todas las tarifas)."""
    try:
        raw = pd.read_excel(f, sheet_name=0, header=None)
    except Exception:
        return pd.DataFrame(columns=['Fecha', 'Total Viajes'])
    _filas = []
    for _i in range(len(raw)):
        _fe = pd.to_datetime(raw.iloc[_i, 0], errors='coerce')
        if pd.isna(_fe):
            continue
        _vals = pd.to_numeric(raw.iloc[_i, 1:], errors='coerce')
        _tot = float(_vals.sum())
        if start_date <= _fe.date() <= end_date:
            _filas.append({'Fecha': _fe.normalize(), 'Total Viajes': _tot})
    if not _filas:
        return pd.DataFrame(columns=['Fecha', 'Total Viajes'])
    return pd.DataFrame(_filas)

def procesar_carga_pasajeros(f, start_date, end_date):
    try:
        is_csv = f.name.lower().endswith('.csv')
        if is_csv:
            try: df = pd.read_csv(f, header=None, encoding='utf-8')
            except UnicodeDecodeError: 
                f.seek(0); df = pd.read_csv(f, header=None, encoding='latin-1')
        else:
            eu = "xlrd" if f.name.lower().endswith(".xls") else "openpyxl"
            df = pd.read_excel(f, engine=eu, header=None)
            
        h_idx = next((i for i in range(min(30, len(df))) if 'THDR' in str(df.iloc[i].values).upper() or 'VIAJE' in str(df.iloc[i].values).upper()), None)
        
        if h_idx is not None:
            f.seek(0)
            if is_csv:
                try: df = pd.read_csv(f, header=h_idx, encoding='utf-8')
                except UnicodeDecodeError:
                    f.seek(0); df = pd.read_csv(f, header=h_idx, encoding='latin-1')
            else:
                df = pd.read_excel(f, engine=eu, header=h_idx)
                
            df.columns = [str(c).strip() for c in df.columns]
            
            c_fecha = next((c for c in df.columns if 'FECHA' in str(c).upper() or 'DIA' in str(c).upper() or 'DATE' in str(c).upper()), None)
            if c_fecha:
                df['Fecha'] = pd.to_datetime(df[c_fecha], dayfirst=True, errors='coerce').dt.normalize()
                df = df.dropna(subset=['Fecha'])
                df = df[(df['Fecha'].dt.date >= start_date) & (df['Fecha'].dt.date <= end_date)]
            elif 'Fecha' in df.columns:
                df['Fecha'] = pd.to_datetime(df['Fecha'], dayfirst=True, errors='coerce').dt.normalize()
                df = df.dropna(subset=['Fecha'])
                df = df[(df['Fecha'].dt.date >= start_date) & (df['Fecha'].dt.date <= end_date)]
            
            if df.empty:
                return pd.DataFrame()
                
            c_tot = next((c for c in df.columns if 'TOTAL' in str(c).upper() and 'BORDO' in str(c).upper()), None)
            if c_tot:
                df['Total a Bordo'] = pd.to_numeric(df[c_tot], errors='coerce').fillna(0)
            elif 'Total a Bordo' in df.columns:
                df['Total a Bordo'] = pd.to_numeric(df['Total a Bordo'], errors='coerce').fillna(0)
                
            c_est_max = next((c for c in df.columns if 'ESTACI' in str(c).upper() and 'MAX' in _norm(c)), None)
            if c_est_max:
                df['Estación Máxima'] = df[c_est_max]
                
            return df
        return pd.DataFrame()
    except Exception:
        return pd.DataFrame()

def fig_perfil_velocidades():
    kms = [(s[0]+s[1])/2/1000 for s in SPEED_PROFILE]
    vels_n = [s[3] if s[3] > 0 else 0 for s in SPEED_PROFILE]
    vels_r = [s[4] if s[4] > 0 else 0 for s in SPEED_PROFILE]
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=kms, y=vels_n, mode='lines', name='Vel. Normal',
                              line=dict(color='#005195', width=2), fill='tozeroy', fillcolor='rgba(0,81,149,0.12)'))
    fig.add_trace(go.Scatter(x=kms, y=vels_r, mode='lines', name='Vel. RM', line=dict(color='#E85500', width=1.5, dash='dot')))
    for est, km_est in zip(ESTACIONES, KM_ACUM):
        fig.add_vline(x=km_est, line_width=1, line_dash='dot', line_color='gray')
        fig.add_annotation(x=km_est, y=125, text=est[:3], showarrow=False, font=dict(size=8, color='#555'), textangle=-90)
    fig.update_layout(title='Perfil de velocidades — Vía 1', xaxis_title='km desde Puerto', yaxis_title='km/h', height=300, margin=dict(t=40, b=20))
    return fig

def _armar_df_ops(all_ops, all_tr, all_fact_full, all_prmte_full, all_seat):
    """Tabla diaria: odómetro y tren-km del UMR (sin SFE en pruebas), energía por fuente y jerarquía
    Factura > PRMTE > SEAT. La usa la carga principal y la línea base del año anterior. Devuelve (df_ops, seat_dups)."""
    df_ops=pd.DataFrame(all_ops).groupby("Fecha").agg({"Odómetro [km]":"sum","Tren-Km [km]":"sum"}).reset_index()
    # --- Excluir SFE en pruebas del Odómetro/Tren-Km ---
    # Regla comercial v35: SFE-412 desde 22-abr-2026 y SFE-410/411 desde
    # 25-sep-2026. Fuera de esas fechas sus km siguen como pruebas aparte.
    # El km diario de cada SFE se toma de all_tr (odómetro por tren). Se descuenta del
    # total del UMR el aporte de los SFE que NO deben contar en cada fecha.
    _sfe_desc = {}
    if all_tr:
        _dt_all = pd.DataFrame(all_tr)
        if {'Tren', 'Fecha', 'Valor'}.issubset(_dt_all.columns):
            _dt_all['Fecha'] = pd.to_datetime(_dt_all['Fecha'], errors='coerce').dt.normalize()
            _dt_all['Valor'] = pd.to_numeric(_dt_all['Valor'], errors='coerce')
            if 'Clase' in _dt_all.columns and (_dt_all['Clase'] == 'km').any():
                _dt_km = _dt_all[_dt_all['Clase'] == 'km']
            else:
                _dt_km = _dt_all[_dt_all['Valor'] < 50000]
            _dt_km = _dt_km.dropna(subset=['Fecha', 'Valor'])
            _es_sfe = _dt_km['Tren'].astype(str).str.upper().str.startswith('SFE')
            # Km diario total por fecha reconstruido desde all_tr (todos los trenes)
            _tot_tr = _dt_km.groupby('Fecha')['Valor'].sum()
            # Km diario de SFE por fecha
            _tot_sfe_dia = _dt_km[_es_sfe].groupby('Fecha')['Valor'].sum()
            for _fe_s in _tot_sfe_dia.index:
                # Solo descontar si el total del UMR para esa fecha INCLUYE el SFE
                # (se compara la suma por tren con el odómetro del df_ops de esa fecha)
                _od_umr = df_ops.loc[pd.to_datetime(df_ops['Fecha']).dt.normalize() == _fe_s, 'Odómetro [km]']
                _od_umr = float(_od_umr.iloc[0]) if len(_od_umr) else 0.0
                _tot_con_sfe = float(_tot_tr.get(_fe_s, 0.0))
                _incluye_sfe = _od_umr > (_tot_con_sfe - float(_tot_sfe_dia[_fe_s])) + 1.0
                if not _incluye_sfe:
                    continue
                # Sumar el km de los SFE que NO deben contar en esa fecha
                _sfe_fe = _dt_km[_es_sfe & (_dt_km['Fecha'] == _fe_s)]
                for _, _rs in _sfe_fe.iterrows():
                    _cuenta = _sfe_comercial(_rs['Tren'],_fe_s)
                    if not _cuenta:
                        _sfe_desc[_fe_s] = _sfe_desc.get(_fe_s, 0.0) + float(_rs['Valor'])
    if _sfe_desc:
        _sfe_ser = pd.Series(_sfe_desc)
        _df_desc = pd.DataFrame({'Fecha': _sfe_ser.index, '_sfe_km': _sfe_ser.values})
        _df_desc['Fecha'] = pd.to_datetime(_df_desc['Fecha']).dt.normalize()
        df_ops['Fecha'] = pd.to_datetime(df_ops['Fecha']).dt.normalize()
        df_ops = df_ops.merge(_df_desc, on='Fecha', how='left')
        df_ops['_sfe_km'] = df_ops['_sfe_km'].fillna(0.0)
        df_ops['Odómetro [km]'] = (df_ops['Odómetro [km]'] - df_ops['_sfe_km']).clip(lower=0)
        df_ops = df_ops.drop(columns=['_sfe_km'])
    df_f_d=(pd.DataFrame(all_fact_full).groupby("Fecha")["Consumo"].sum().reset_index().rename(columns={"Consumo":"E_Fact"}) if all_fact_full else pd.DataFrame(columns=["Fecha","E_Fact"]))
    df_p_d=(pd.DataFrame(all_prmte_full).groupby("Fecha")["Consumo"].sum().reset_index().rename(columns={"Consumo":"E_Prmte"}) if all_prmte_full else pd.DataFrame(columns=["Fecha","E_Prmte"]))
    # SEAT: si una misma fecha viene en más de un archivo, manda el archivo de ESE mes
    # (antes se sumaban y el día quedaba duplicado).
    if all_seat:
        _dse = pd.DataFrame(all_seat)
        _dse['Fecha'] = pd.to_datetime(_dse['Fecha']).dt.normalize()
        for _c in ['E_Total', 'E_Tr', 'E_12']:
            _dse[_c] = pd.to_numeric(_dse[_c], errors='coerce')
        if '_arch' not in _dse.columns:
            _dse['_arch'] = ''
        for _c in ['_arch_anio', '_arch_mes']:
            if _c not in _dse.columns:
                _dse[_c] = np.nan
        # Un mismo archivo puede traer varias filas del día: se suman dentro del archivo
        _dse = _dse.groupby(['Fecha', '_arch', '_arch_anio', '_arch_mes'], as_index=False, dropna=False).agg(
            {'E_Total': 'sum', 'E_Tr': 'sum', 'E_12': 'sum'})
        # Prioridad 1 = el archivo corresponde al mes/año de la fecha
        _fx = pd.to_datetime(_dse['Fecha'])
        _dse['_prio'] = ((_dse['_arch_mes'] == _fx.dt.month) & (_dse['_arch_anio'] == _fx.dt.year)).astype(int)
        _n_antes = len(_dse)
        _dse = _dse.sort_values(['Fecha', '_prio', '_arch'], ascending=[True, False, True])
        _dse = _dse.drop_duplicates(subset=['Fecha'], keep='first')
        _seat_dups = _n_antes - len(_dse)
        df_s_d = _dse[['Fecha', 'E_Total', 'E_Tr', 'E_12']].rename(
            columns={"E_Total": "E_Seat_T", "E_Tr": "E_Seat_Tr", "E_12": "E_Seat_12"})
    else:
        df_s_d = pd.DataFrame(columns=["Fecha", "E_Seat_T", "E_Seat_Tr", "E_Seat_12"])
        _seat_dups = 0
    
    for dff in [df_ops,df_f_d,df_p_d,df_s_d]: dff['Fecha']=pd.to_datetime(dff['Fecha']).dt.normalize()
    df_ops=(df_ops.merge(df_f_d,on="Fecha",how="left").merge(df_p_d,on="Fecha",how="left").merge(df_s_d,on="Fecha",how="left").fillna(0))
    
    df_ops['Tipo Día'] = df_ops['Fecha'].apply(lambda x: get_tipo_dia(x.date() if pd.notna(x) else None))
    df_ops['Nombre Feriado'] = df_ops['Fecha'].apply(lambda x: obtener_nombre_feriado(x.date() if pd.notna(x) else None))
    df_ops['Fecha (ES)'] = df_ops['Fecha'].apply(obtener_fecha_es)

    # Proporción tracción / baja tensión del período, según la SUMA del SEAT (no un valor fijo).
    # Se usa como respaldo para los días que no traen SEAT propio; los que sí lo traen usan su % diario.
    _sT = pd.to_numeric(df_ops.get('E_Seat_T', pd.Series(dtype=float)), errors='coerce').fillna(0).sum()
    _sTr = pd.to_numeric(df_ops.get('E_Seat_Tr', pd.Series(dtype=float)), errors='coerce').fillna(0).sum()
    _s12 = pd.to_numeric(df_ops.get('E_Seat_12', pd.Series(dtype=float)), errors='coerce').fillna(0).sum()
    if _sT > 0:
        _r_tr_periodo = _sTr / _sT
        _r_12_periodo = _s12 / _sT
    else:
        _r_tr_periodo, _r_12_periodo = 0.85, 0.15

    def jerarquia(row):
        if row['E_Fact']>0:    tot,src=row['E_Fact'],"Factura"
        elif row['E_Prmte']>0:  tot,src=row['E_Prmte'],"PRMTE"
        elif row['E_Seat_T']>0: tot,src=row['E_Seat_T'],"SEAT"
        else: return 0,0,0,0,0,"N/A"
        # % del día si trae SEAT; si no, el % del período (suma del SEAT), no un valor fijo
        if row['E_Seat_T']>0:
            r_tr=row['E_Seat_Tr']/row['E_Seat_T']
            r_12=row['E_Seat_12']/row['E_Seat_T']
        else:
            r_tr=_r_tr_periodo
            r_12=_r_12_periodo
        return tot,tot*r_tr,tot*r_12,r_tr*100,r_12*100,src
        
    df_ops[['E_Total','E_Tr','E_12','% Tracción','% 12 kV','Fuente']]=df_ops.apply(jerarquia,axis=1,result_type='expand')
    df_ops['IDE (kWh/km)']=df_ops.apply(lambda r: r['E_Tr']/r['Odómetro [km]'] if r['Odómetro [km]']>0 else 0,axis=1)
    df_ops['UMR (%)'] = df_ops.apply(lambda r: (r['Tren-Km [km]'] / r['Odómetro [km]']) * 100 if r['Odómetro [km]'] > 0 else 0, axis=1)
    return df_ops, _seat_dups

def _incid_leer(f):
    """Lee un archivo de Incidentes PCC y devuelve la tabla con sus encabezados (None si no se reconoce).
    La usan la carga principal y la pestaña de causa raíz."""
    _ei = "xlrd" if f.name.lower().endswith(".xls") else "openpyxl"
    _d0 = pd.read_excel(f, header=None, engine=_ei)
    _hr = None
    for _i in range(min(12, len(_d0))):
        if (_d0.iloc[_i].astype(str).str.strip() == 'Descripción').any():
            _hr = _i; break
    if _hr is None:
        for _i in range(min(12, len(_d0))):
            if (_d0.iloc[_i].astype(str).str.strip() == 'Subtipo incidente').any():
                _hr = _i; break
    if _hr is None:
        return None
    return pd.read_excel(f, header=_hr, engine=_ei)


def _incid_filas(_di, start_date, end_date):
    """Todos los incidentes del rango, con los campos que indican afectación (una fila por incidente)."""
    _col_desc = next((c for c in _di.columns if str(c).strip().lower().startswith('descrip')), None)
    _col_fec = next((c for c in _di.columns if 'ocurrencia' in str(c).strip().lower()), None)
    if _col_desc is None or _col_fec is None:
        return []
    def _col_inc(*_cl):
        for _c in _di.columns:
            _cn = str(_c).strip().lower()
            if any(_k in _cn for _k in _cl):
                return _c
        return None
    _c_afecta = _col_inc('afecta operaci', 'afecta la operaci')
    _c_tipo = _col_inc('tipo incidente')
    _c_cat = _col_inc('categoria incidente', 'categoría incidente')
    _c_timp = _col_inc('tiempo de impacto')
    _c_serv = _col_inc('numero de servicio', 'número de servicio')
    _c_tri = _col_inc('tramo inicial')
    _c_trf = _col_inc('tramo final')
    _rows = []
    for _, _rf in _di.iterrows():
        _fof = pd.to_datetime(_rf.get(_col_fec), dayfirst=True, errors='coerce')
        if pd.isna(_fof) or not (start_date <= _fof.date() <= end_date):
            continue
        _afv = str(_rf.get(_c_afecta, '')).strip().upper() if _c_afecta else ''
        _afecta = _afv in ('SI', 'SÍ', 'YES', 'TRUE', '1', 'VERDADERO')
        _timp = pd.to_numeric(_rf.get(_c_timp), errors='coerce') if _c_timp else np.nan
        _rows.append({
            'Fecha': _fof.normalize(),
            'Afecta operación': _afecta,
            'Tipo incidente': (str(_rf.get(_c_tipo, '')).strip() if _c_tipo else ''),
            'Categoría': (str(_rf.get(_c_cat, '')).strip() if _c_cat else ''),
            'Tiempo impacto (min)': float(_timp) if pd.notna(_timp) else np.nan,
            'N° servicio': (str(_rf.get(_c_serv, '')).strip() if _c_serv else ''),
            'Tramo ini': (str(_rf.get(_c_tri, '')).strip().upper() if _c_tri else ''),
            'Tramo fin': (str(_rf.get(_c_trf, '')).strip().upper() if _c_trf else ''),
            'Descripción': str(_rf.get(_col_desc, ''))[:200]})
    return _rows


def _oit_archivo(f, start_date, end_date, h_ini=0, h_fin=7):
    """Lee una Consulta OIT y devuelve (órdenes de prueba SFE cerradas de madrugada dentro del rango, diagnóstico).
    La usan la carga principal y la pestaña de causa raíz, que la llama año por año."""
    _rows = []
    _eng = "xlrd" if f.name.lower().endswith(".xls") else "openpyxl"
    _raw_o = pd.read_excel(f, header=None, engine=_eng)
    # Detectar la fila de encabezado: la que trae Área / Sistema / Trabajos
    _hdr = None
    for _r in range(min(20, len(_raw_o))):
        _fila = " | ".join(_norm(v) for v in _raw_o.iloc[_r].tolist() if pd.notna(v))
        if ('AREA' in _fila) and ('SISTEMA' in _fila or 'TRABAJO' in _fila):
            _hdr = _r
            break
    if _hdr is None:
        for _r in range(min(20, len(_raw_o))):
            _fila = " | ".join(_norm(v) for v in _raw_o.iloc[_r].tolist() if pd.notna(v))
            if 'SISTEMA' in _fila or 'TRABAJO' in _fila or 'CIERRE' in _fila:
                _hdr = _r
                break
    if _hdr is None:
        return [], {'error': 'No se encontró la fila de encabezados. Primeras filas: ' +
                             " || ".join(" | ".join(str(v) for v in _raw_o.iloc[_r].tolist()[:6] if pd.notna(v)) for _r in range(min(3, len(_raw_o))))}
    _do = pd.read_excel(f, header=_hdr, engine=_eng)
    _do = _do.dropna(how='all')

    def _col_oit(*_claves):
        for _c in _do.columns:
            _cn = _norm(_c)
            if any(_k in _cn for _k in _claves):
                return _c
        return None
    _c_area = _col_oit('AREA')
    _c_sist = _col_oit('SISTEMA')
    _c_trab = _col_oit('TRABAJO', 'DESCRIP', 'DETALLE', 'GLOSA')
    _c_ot = _col_oit('OIT', 'NUMERO', 'FOLIO', 'ORDEN')
    _c_eq = _col_oit('EQUIPO', 'UNIDAD', 'MOVIL', 'SERIE', 'FLOTA')
    # Fecha de cierre: primero la que tenga FECHA+CIERRE (evita "Comentarios cierre",
    # que es texto). Si no, cualquier columna de fecha con hora que diga cierre/fin.
    _c_cierre = None
    for _c in _do.columns:
        _cn = _norm(_c)
        if ('FECHA' in _cn or 'F.' in _cn) and ('CIERRE' in _cn or 'CIERR' in _cn or 'TERMINO' in _cn or 'FIN' in _cn):
            _c_cierre = _c
            break
    if _c_cierre is None:
        for _c in _do.columns:
            _cn = _norm(_c)
            if 'CIERRE' in _cn and 'COMENTARIO' not in _cn and 'RESPONSABLE' not in _cn and 'USUARIO' not in _cn:
                # que sea parseable como fecha antes de aceptarla
                _try = pd.to_datetime(_do[_c], errors='coerce', dayfirst=True)
                if _try.notna().sum() > 0:
                    _c_cierre = _c
                    break

    _txt_sist = _do[_c_sist].astype(str) if _c_sist else pd.Series([''] * len(_do), index=_do.index)
    _txt_trab = _do[_c_trab].astype(str) if _c_trab else pd.Series([''] * len(_do), index=_do.index)
    _txt_eq = _do[_c_eq].astype(str) if _c_eq else pd.Series([''] * len(_do), index=_do.index)
    _txt_all = (_txt_sist + ' ' + _txt_trab + ' ' + _txt_eq).map(_norm)
    # SFE en cualquier parte del texto (pegado o separado): "SFE", "SFE412", "SFE 413"…
    _es_sfe = _txt_all.str.contains('SFE', na=False)
    # Área: se registra a qué área pertenece cada orden, pero NO se filtra por ella.
    # Las pruebas de SFE de madrugada pueden estar en Material Rodante, Vías u otra área.
    _area_val = _do[_c_area].astype(str) if _c_area else pd.Series(['(sin área)'] * len(_do), index=_do.index)
    # Fecha y hora de cierre (formato típico "dd-mm-aaaa HH:MM")
    if _c_cierre:
        _fc = pd.to_datetime(_do[_c_cierre], format='%d-%m-%Y %H:%M', errors='coerce')
        if _fc.isna().all():
            _fc = pd.to_datetime(_do[_c_cierre], errors='coerce', dayfirst=True)
        else:
            _fc = _fc.fillna(pd.to_datetime(_do[_c_cierre], errors='coerce', dayfirst=True))
    else:
        _fc = pd.Series([pd.NaT] * len(_do), index=_do.index)
    _hora_c = _fc.dt.hour + _fc.dt.minute / 60.0
    _es_madrugada = (_hora_c >= h_ini) & (_hora_c < h_fin)
    _en_rango = _fc.dt.date.map(lambda _d: (pd.notna(_d) and start_date <= _d <= end_date))
    # Filtro: SFE + fecha de cierre en madrugada + dentro del rango (sin filtrar por área)
    _sel = _es_sfe & _fc.notna() & _es_madrugada & _en_rango
    # Diagnóstico: cuántas filas sobreviven a cada filtro
    _diag = {
        'error': None,
        'header_fila': _hdr,
        'columnas': list(_do.columns),
        'col_area': _c_area, 'col_sistema': _c_sist, 'col_trabajos': _c_trab,
        'col_cierre': _c_cierre,
        'filas': len(_do),
        'con_sfe': int(_es_sfe.sum()),
        'fecha_valida': int(_fc.notna().sum()),
        'madrugada': int((_fc.notna() & _es_madrugada).sum()),
        'en_rango_fechas': int(_en_rango.sum()),
        'seleccionadas': int(_sel.sum())}
    for _i in _do.index[_sel]:
        _f_cierre = _fc.loc[_i]
        _txt_i = _txt_all.loc[_i]
        _mn = re.search(r'SFE[\s\-_.]*(\d{3})', _txt_i) or re.search(r'\b(4[01]\d)\b', _txt_i)
        _n_sfe = int(_mn.group(1)) if _mn else np.nan
        _rows.append({
            'Fecha': _f_cierre.normalize(),
            'Hora cierre': _f_cierre.strftime('%H:%M'),
            'Hora_n': float(_hora_c.loc[_i]),
            'SFE': (f"SFE {_n_sfe}" if pd.notna(_n_sfe) else "SFE (sin número)"),
            'N_SFE': _n_sfe,
            'Área': str(_area_val.loc[_i]).strip(),
            'Sistema': (str(_do.at[_i, _c_sist])[:80] if _c_sist else ''),
            'Trabajos': (str(_do.at[_i, _c_trab])[:150] if _c_trab else ''),
            'OT': (str(_do.at[_i, _c_ot]) if _c_ot else '')})
    return _rows, _diag


# ===== Carga de pasajeros por viaje: tramos, bloques de 15 min y energía de cada viaje =====
# Las usan la pestaña 🔗 BI (bloques de 15 min) y 👥 Pasajeros › Por servicio (pasajeros, ocupación y energía de cada viaje).
# Capacidad de pasajeros de una unidad (2 coches) por tipo de tren. 367 es la capacidad informada del X'Trapolis Modular;
# cámbiala aquí para dejarla fija (en la pestaña también se puede ajustar sin tocar el código).
_CAP_UNIDAD = {'XT-100': 367, 'XT-M': 367, 'SFE': 367}
_JORNADA_TXT = {'L': 'Laboral', 'S': 'Sábado', 'D/F': 'Domingo y festivo'}
# Km de cada estación según el código de columna del export de Carga (PUE, BEL, ..., LIM)
_KM_PAX = {PAX_COL_CODE[_e]: _KM_ESTACION[_norm(_e)] for _e in ESTACIONES if _norm(_e) in _KM_ESTACION}

def _integrar_15(_ini, _fin, _val, _n):
    """Reparte un valor constante en [ini, fin) (minutos desde el inicio) en bloques de 15 min. Devuelve valor·minuto por bloque."""
    _out = np.zeros(_n)
    _ok = np.isfinite(_ini) & np.isfinite(_fin) & (_fin > _ini) & np.isfinite(_val) & (_val != 0)
    _ini, _fin, _val = _ini[_ok], _fin[_ok], _val[_ok]
    if not len(_ini):
        return _out
    _b0 = np.floor(_ini / 15).astype(int); _b1 = np.floor((_fin - 1e-9) / 15).astype(int)
    for _j in range(int((_b1 - _b0).max()) + 1):
        _b = _b0 + _j; _s = _b <= _b1
        _w = np.clip(np.minimum(_fin[_s], (_b[_s] + 1) * 15.0) - np.maximum(_ini[_s], _b[_s] * 15.0), 0, None) * _val[_s]
        _bb = _b[_s]; _in = (_bb >= 0) & (_bb < _n)
        _out += np.bincount(_bb[_in], weights=_w[_in], minlength=_n)[:_n]
    return _out

def _viajes_y_tramos(_df, _t_ini, con_viaje=False):
    """Por viaje: inicio, fin y unidades (doble = 2). Por tramo entre estaciones: inicio, fin, pasajeros a bordo y km.
    La hora de paso por cada estación se interpola entre Hora Origen y Hora Fin según el km recorrido."""
    _cods = [c for c in _df.columns if c in _KM_PAX]
    _cho = next((c for c in _df.columns if 'HORA' in str(c).upper() and 'ORIG' in str(c).upper()), None)
    _chf = next((c for c in _df.columns if 'HORA' in str(c).upper() and 'FIN' in str(c).upper()), None)
    if len(_cods) < 2 or _cho is None or _chf is None:
        return None
    _cm2 = next((c for c in _df.columns if 'MOTRIZ' in str(c).upper() and '2' in str(c)), None)
    _fe = pd.to_datetime(_df['Fecha'], errors='coerce').dt.normalize()
    _t0 = ((_fe + pd.to_timedelta(_df[_cho].astype(str).str.strip(), errors='coerce')) - _t_ini).dt.total_seconds().to_numpy() / 60
    _t1 = ((_fe + pd.to_timedelta(_df[_chf].astype(str).str.strip(), errors='coerce')) - _t_ini).dt.total_seconds().to_numpy() / 60
    _t1 = np.where(_t1 < _t0, _t1 + 1440, _t1)  # viaje que cruza la medianoche
    _uni = np.where(pd.to_numeric(_df[_cm2], errors='coerce').fillna(0).to_numpy() > 0, 2.0, 1.0) if _cm2 else np.ones(len(_df))
    _K = np.array([_KM_PAX[c] for c in _cods], dtype=float); _S = len(_cods)
    _L = _df[_cods].apply(pd.to_numeric, errors='coerce').fillna(0).to_numpy(float)
    # Recorrido según la carga: origen = 1ª estación con pasajeros; destino = la siguiente a la última con pasajeros
    _pos = _L > 0; _hay = _pos.any(axis=1)
    _o = np.where(_hay, _pos.argmax(axis=1), 0)
    _d = np.where(_hay, np.minimum(_S - _pos[:, ::-1].argmax(axis=1), _S - 1), _S - 1)
    _span = np.abs(_K[_d] - _K[_o]); _span = np.where(_span > 0, _span, np.nan)
    _T = _t0[:, None] + (_t1 - _t0)[:, None] * (np.abs(_K[None, :] - _K[_o][:, None]) / _span[:, None])
    _k = np.arange(_S - 1)[None, :]
    _ok = (_k >= _o[:, None]) & (_k < _d[:, None]) & _hay[:, None]
    _km = np.broadcast_to(np.abs(np.diff(_K))[None, :], _ok.shape)
    _res = ((_t0, _t1, _uni), (_T[:, :-1][_ok], _T[:, 1:][_ok], _L[:, :-1][_ok], _km[_ok]))
    if con_viaje:  # además: viaje de cada tramo, origen y destino de cada viaje y su carga máxima
        return _res + ({'viaje': np.nonzero(_ok)[0], 'o': _o, 'd': _d, 'cods': _cods, 'carga_max': _L.max(axis=1)},)
    return _res


def _bloques_15(_c_list, _prmte):
    """Bloques de 15 min de los días con Carga de pasajeros: trenes, unidades, pasajeros a bordo y pax-km en
    circulación (de los viajes de Carga) y kWh del PRMTE del mismo bloque. Devuelve (bloques, inicio del primer día)."""
    _fe_c = pd.to_datetime(pd.concat([d['Fecha'] for d in _c_list]), errors='coerce').dt.normalize().dropna()
    _t_ini = _fe_c.min(); _n_b = int(((_fe_c.max() - _t_ini).days + 2) * 96)
    _acc = np.zeros((4, _n_b))
    for _dc in _c_list:
        _r_vt = _viajes_y_tramos(_dc, _t_ini)
        if _r_vt is None:
            continue
        (_t0, _t1, _un), (_si, _sf, _sl, _sk) = _r_vt
        _dur = _sf - _si
        _acc[0] += _integrar_15(_t0, _t1, np.ones_like(_t0), _n_b)
        _acc[1] += _integrar_15(_t0, _t1, _un, _n_b)
        _acc[2] += _integrar_15(_si, _sf, _sl, _n_b)
        _acc[3] += _integrar_15(_si, _sf, np.divide(_sl * _sk, _dur, out=np.zeros_like(_dur), where=_dur > 0), _n_b)
    _q = pd.DataFrame({'ts': _t_ini + pd.to_timedelta(np.arange(_n_b) * 15, unit='min'),
                       'Trenes': _acc[0] / 15, 'Unidades': _acc[1] / 15, 'Pax a bordo': _acc[2] / 15, 'Pax-km': _acc[3]})
    _pr = pd.DataFrame(_prmte)
    _pr['ts'] = pd.to_datetime(_pr['Fecha'], errors='coerce').dt.normalize() + pd.to_timedelta(_pr['15min'].astype(str) + ':00', errors='coerce')
    _e15 = _pr.dropna(subset=['ts']).groupby('ts', as_index=False)['Consumo'].sum().rename(columns={'Consumo': 'kWh'})
    _bi = _q.merge(_e15, on='ts', how='inner')
    _bi = _bi[_bi['ts'].dt.date.isin(set(_fe_c.dt.date))].sort_values('ts').reset_index(drop=True)
    return _bi, _t_ini


def _modelo_15(_bi):
    """kWh de cada bloque = base sin trenes + extra con servicio + kWh por unidad × unidades en circulación. La base es la
    mediana de los bloques sin trenes. Devuelve (base, extra con servicio, kWh por unidad)."""
    _U = _bi['Unidades'].to_numpy(float); _y = _bi['kWh'].to_numpy(float); _srv = _U > 0.05
    _base = float(np.median(_y[~_srv])) if (~_srv).any() else 0.0
    _bs, _bu = np.linalg.lstsq(np.column_stack([np.ones(int(_srv.sum())), _U[_srv]]), _y[_srv] - _base, rcond=None)[0]
    return _base, _bs, _bu


def _integrar_tasa(_ini, _fin, _val, _tasa):
    """Para cada intervalo [ini, fin) (minutos) con un valor por minuto, suma valor × minutos × tasa del bloque de 15 min."""
    _n = len(_tasa)
    _out = np.zeros(len(_ini))
    _ok = np.isfinite(_ini) & np.isfinite(_fin) & (_fin > _ini) & np.isfinite(_val) & (_val != 0)
    if not _ok.any():
        return _out
    _i0, _f0 = np.where(_ok, _ini, 0.0), np.where(_ok, _fin, 1.0)
    _b0 = np.floor(_i0 / 15).astype(int); _b1 = np.floor((_f0 - 1e-9) / 15).astype(int)
    for _j in range(int((_b1 - _b0)[_ok].max()) + 1):
        _b = _b0 + _j
        _s = _ok & (_b <= _b1) & (_b >= 0) & (_b < _n)
        _w = np.clip(np.minimum(_f0, (_b + 1) * 15.0) - np.maximum(_i0, _b * 15.0), 0, None) * np.where(_ok, _val, 0.0)
        _out[_s] += _w[_s] * _tasa[_b[_s]]
    return _out


def _energia_por_viaje(_cargas, _prmte, _thdrs=None):
    """Cada viaje de Carga de pasajeros con su hora de salida programada (del THDR), pasajeros, carga máxima, pax-km,
    unidades, tipo de tren, tipo de jornada y energía estimada. La energía de cada bloque de 15 min del PRMTE, sin la base
    sin trenes ni el extra con servicio (estaciones, iluminación), se reparte entre los trenes que circulan en ese bloque
    según unidades × km recorridos en él (doble = 2 unidades); la suma de los viajes calza con esa energía.
    _cargas y _thdrs: {'Vía 1': df, 'Vía 2': df}. Devuelve (tabla de viajes, resumen del reparto)."""
    _c_list = [d for d in _cargas.values() if d is not None and not getattr(d, 'empty', True) and 'Fecha' in d.columns]
    if not _c_list or not _prmte:
        return pd.DataFrame(), {}
    _bi, _t_ini = _bloques_15(_c_list, _prmte)
    if len(_bi) < 96 or not (_bi['Unidades'].std() > 0):
        return pd.DataFrame(), {}
    _base, _bs, _bu = _modelo_15(_bi)
    _fe_max = pd.to_datetime(pd.concat([d['Fecha'] for d in _c_list]), errors='coerce').dt.normalize().max()
    _n_b = int(((_fe_max - _t_ini).days + 2) * 96)
    _ix = ((_bi['ts'] - _t_ini).dt.total_seconds() // 900).astype(int).to_numpy()
    _en = (_ix >= 0) & (_ix < _n_b)
    _es = np.zeros(_n_b)  # energía de los trenes en cada bloque: lo medido sin la base ni el extra con servicio
    _es[_ix[_en]] = np.where(_bi['Unidades'].to_numpy(float) > 0.05, np.clip(_bi['kWh'].to_numpy(float) - _base - _bs, 0, None), 0.0)[_en]
    _ukm, _det = np.zeros(_n_b), []
    for _via, _dc in _cargas.items():
        if _dc is None or getattr(_dc, 'empty', True) or 'Fecha' not in _dc.columns:
            continue
        _dc = _dc.reset_index(drop=True)
        _r = _viajes_y_tramos(_dc, _t_ini, con_viaje=True)
        if _r is None:
            continue
        (_t0, _t1, _un), (_si, _sf, _sl, _sk), _ex = _r
        _dur = _sf - _si
        _vel = np.divide(_sk * _un[_ex['viaje']], _dur, out=np.zeros_like(_dur), where=_dur > 0)  # unidad-km por minuto
        _ukm += _integrar_15(_si, _sf, _vel, _n_b)
        _det.append((_via, _dc, _t0, _un, _si, _sf, _sl, _sk, _ex, _vel))
    _tasa = np.divide(_es, _ukm, out=np.zeros_like(_es), where=_ukm > 0)  # kWh por unidad-km de cada bloque
    _partes = []
    for _via, _dc, _t0, _un, _si, _sf, _sl, _sk, _ex, _vel in _det:
        _nv, _vi = len(_t0), _ex['viaje']
        _col = lambda *ks: next((c for c in _dc.columns if all(k in _norm(c) for k in ks)), None)
        _c_tr, _c_tot, _c_cm, _c_em = _col('TREN'), _col('TOTAL'), _col('CARGA', 'MAX'), _col('ESTACION', 'MAX')
        _c_m1, _c_ho, _c_nt = _col('MOTRIZ', '1'), _col('HORA', 'ORIG'), _col('THDR')
        _fe = pd.to_datetime(_dc['Fecha'], errors='coerce').dt.normalize()
        _ho = pd.to_timedelta(_dc[_c_ho].astype(str).str.strip(), errors='coerce') if _c_ho else pd.Series(pd.NaT, index=_dc.index)
        # Hora de salida programada: del THDR de la misma vía, con el N° THDR del viaje (= N° de viaje del THDR de ese día)
        _pg = pd.Series(np.nan, index=_dc.index, dtype=object)
        _th = (_thdrs or {}).get(_via)
        if _c_nt and _th is not None and not getattr(_th, 'empty', True) and {'Viaje', 'Hora Salida Programada', 'Fecha_Op'}.issubset(_th.columns):
            _kt = (pd.to_datetime(_th['Fecha_Op'], errors='coerce').dt.strftime('%Y-%m-%d') + '|'
                   + pd.to_numeric(_th['Viaje'], errors='coerce').astype('Int64').astype(str))
            _prog = pd.Series(_th['Hora Salida Programada'].astype(str).str[:5].values, index=_kt.values)
            _prog = _prog[~_prog.index.duplicated() & _prog.str.match(r'^\d{2}:\d{2}$')]
            _kc = _fe.dt.strftime('%Y-%m-%d') + '|' + pd.to_numeric(_dc[_c_nt], errors='coerce').astype('Int64').astype(str)
            _pg = _kc.map(_prog)
        _cods = _ex['cods']
        _cmax = pd.to_numeric(_dc[_c_cm], errors='coerce') if _c_cm else pd.Series(np.nan, index=_dc.index)
        _cmax = _cmax.fillna(pd.Series(_ex['carga_max'], index=_dc.index))
        _partes.append(pd.DataFrame({
            'Fecha': _fe, 'Vía': _via,
            'Tren': pd.to_numeric(_dc[_c_tr], errors='coerce') if _c_tr else np.nan,
            'Programada': _pg,
            'Sale_real_min': _ho.dt.total_seconds() / 60,
            'Trayecto': [f"{_cods[o]} → {_cods[d]}" for o, d in zip(_ex['o'], _ex['d'])],
            'Tipo de tren': (_dc[_c_m1].map(_tipo_tren) if _c_m1 else 'Sin asignar'),
            'Unidades': _un,
            'Pasajeros': pd.to_numeric(_dc[_c_tot], errors='coerce') if _c_tot else np.nan,
            'Carga máxima': _cmax,
            'Estación máxima': _dc[_c_em].astype(str) if _c_em else '',
            'Pax-km': np.bincount(_vi, weights=_sl * _sk, minlength=_nv),
            'Km': np.bincount(_vi, weights=_sk, minlength=_nv),
            'kWh': np.bincount(_vi, weights=_integrar_tasa(_si, _sf, _vel, _tasa), minlength=_nv)}))
    if not _partes:
        return pd.DataFrame(), {}
    _vj = pd.concat(_partes, ignore_index=True)
    _vj = _vj[_vj['Fecha'].notna() & (_vj['Km'] > 0)].reset_index(drop=True)
    _jor = {_f: _JORNADA_TXT.get(get_tipo_dia(_f.date()), 'Laboral') for _f in _vj['Fecha'].unique()}
    _vj['Jornada'] = _vj['Fecha'].map(_jor)
    # Salida del servicio: la programada; si no está en el THDR, la real redondeada a 5 min (marcada con ~)
    _hm = lambda m: f"{int(m // 60) % 24:02d}:{int(m % 60):02d}"
    _pmin = pd.to_timedelta(_vj['Programada'].where(_vj['Programada'].notna(), None).astype(str) + ':00', errors='coerce').dt.total_seconds() / 60
    _rmin = (_vj['Sale_real_min'] / 5).round() * 5
    _vj['Sale_min'] = _pmin.fillna(_rmin)
    _vj['Sale'] = [(_hm(p) if pd.notna(p) else ('~' + _hm(r) if pd.notna(r) else '')) for p, r in zip(_pmin, _rmin)]
    return _vj, {'base': float(_base), 'extra': float(_bs), 'por_unidad': float(_bu), 'e_trenes': float(_es.sum()), 'e_viajes': float(_vj['kWh'].sum())}


# ===== Temperatura diaria de cada comuna de la línea (Open-Meteo: datos históricos de ECMWF, gratis y sin clave) =====
# La usan la causa raíz y el Constructor de datos. Se guarda en disco (data/_cache) y se vuelve a pedir cada 6 horas como
# máximo. Si el servicio no responde, los análisis siguen sin temperatura y se reintenta a los 15 minutos. Los últimos
# días del año en curso aparecen con unos días de atraso.
_COMUNAS_LINEA = {  # comuna: (latitud, longitud, estaciones de la comuna)
    'Valparaíso': (-33.047, -71.613, ['Puerto', 'Bellavista', 'Francia', 'Baron', 'Portales']),
    'Viña del Mar': (-33.025, -71.552, ['Recreo', 'Miramar', 'Viña del Mar', 'Hospital', 'Chorrillos', 'El Salto']),
    'Quilpué': (-33.047, -71.443, ['Valencia', 'Quilpue', 'El Sol', 'El Belloto']),
    'Villa Alemana': (-33.042, -71.373, ['Las Americas', 'La Concepcion', 'Villa Alemana', 'Sargento Aldea', 'Peñablanca']),
    'Limache': (-32.985, -71.276, ['Limache']),
}
# Umbrales de la causa raíz: «Calor» = grados de máxima sobre _T_CALOR (aire acondicionado); «Frío» = grados de mínima
# bajo _T_FRIO (calefacción). Ambos en °C y con la temperatura de la línea.
_T_CALOR, _T_FRIO = 24.0, 12.0
_CLIMA_COLS = ['Fecha', 'Comuna', 'T_max', 'T_min', 'T_media']


def _t_txt(t, dec=0):
    """Temperatura como texto en formato chileno (sin «-0»); «—» si no hay dato."""
    return '—' if pd.isna(t) else _ncl(round(float(t), dec) + 0.0, dec)


def _peso_comunas():
    """Parte de la línea (km) en cada comuna: cada tramo entre estaciones se reparte mitad y mitad entre sus dos extremos."""
    _est = [(e, _KM_ESTACION[_norm(e)]) for e in ESTACIONES if _norm(e) in _KM_ESTACION]
    _com = {e: c for c, (_, _, es) in _COMUNAS_LINEA.items() for e in es}
    _p = {c: 0.0 for c in _COMUNAS_LINEA}
    for (e0, k0), (e1, k1) in zip(_est[:-1], _est[1:]):
        _d = abs(k1 - k0) / 2
        _p[_com.get(e0, 'Valparaíso')] += _d
        _p[_com.get(e1, 'Limache')] += _d
    _t = sum(_p.values()) or 1.0
    return {c: v / _t for c, v in _p.items()}


@st.cache_resource(show_spinner=False)
def _clima_fallas():
    """Momento del último intento fallido de bajar cada año (compartido por todas las sesiones, para no reintentar en cada clic)."""
    return {}


def _clima_pedir(anio, hasta, diarias):
    import requests
    return requests.get("https://archive-api.open-meteo.com/v1/archive", timeout=(6, 25), params={
        'latitude': ",".join(str(v[0]) for v in _COMUNAS_LINEA.values()),
        'longitude': ",".join(str(v[1]) for v in _COMUNAS_LINEA.values()),
        'start_date': f"{anio}-01-01", 'end_date': hasta.strftime('%Y-%m-%d'),
        'daily': ",".join(diarias), 'timezone': 'America/Santiago'})


@st.cache_data(show_spinner=False, ttl=6 * 3600, max_entries=8)
def _clima_anio(anio):
    """Temperatura máxima, mínima y media de cada día del año en cada comuna [Fecha, Comuna, T_max, T_min, T_media].
    Si el servicio no responde y no hay nada guardado, lanza un error (así no queda en caché un resultado vacío)."""
    _hasta = min(pd.Timestamp(anio, 12, 31), pd.Timestamp.today().normalize() - pd.Timedelta(days=3))
    if _hasta < pd.Timestamp(anio, 1, 1):
        return pd.DataFrame(columns=_CLIMA_COLS)
    _ruta = os.path.join(_CACHE_DIR, f"clima_comunas_{anio}.parquet")
    _prev = pd.DataFrame(columns=_CLIMA_COLS)
    try:
        _prev = pd.read_parquet(_ruta)
        if not _prev.empty and pd.to_datetime(_prev['Fecha']).max() >= _hasta and set(_prev['Comuna']) == set(_COMUNAS_LINEA):
            return _prev
    except Exception:
        pass
    try:
        _diarias = ['temperature_2m_max', 'temperature_2m_min', 'temperature_2m_mean']
        _r = _clima_pedir(anio, _hasta, _diarias)
        if _r.status_code == 400:  # si no acepta la media diaria, se pide máxima y mínima (la media queda como su promedio)
            _diarias = _diarias[:2]
            _r = _clima_pedir(anio, _hasta, _diarias)
        _r.raise_for_status()
        _js = _r.json()
    except Exception:
        if not _prev.empty:
            return _prev  # sin conexión: queda lo que ya estaba guardado
        raise
    _js = _js if isinstance(_js, list) else [_js]  # con varias coordenadas responde una lista, en el mismo orden
    _partes = []
    for _comuna, _j in zip(_COMUNAS_LINEA, _js):
        _d = (_j or {}).get('daily') or {}
        _n = len(_d.get('time') or [])
        _num = lambda k: pd.to_numeric(pd.Series(_d.get(k) or [None] * _n, dtype=object), errors='coerce').to_numpy(float)
        if _n:
            _partes.append(pd.DataFrame({'Fecha': pd.to_datetime(pd.Series(_d['time'], dtype=object), errors='coerce'), 'Comuna': _comuna,
                                         'T_max': _num('temperature_2m_max'), 'T_min': _num('temperature_2m_min'),
                                         'T_media': _num('temperature_2m_mean')}))
    _out = pd.concat(_partes, ignore_index=True) if _partes else pd.DataFrame(columns=_CLIMA_COLS)
    _out = _out.dropna(subset=['Fecha'])
    _out = _out[_out[['T_max', 'T_min']].notna().all(axis=1)].reset_index(drop=True)
    if _out.empty:
        if not _prev.empty:
            return _prev
        raise ValueError("Open-Meteo no devolvió temperaturas")
    _out['T_media'] = _out['T_media'].fillna((_out['T_max'] + _out['T_min']) / 2)
    _out['Fecha'] = pd.to_datetime(_out['Fecha']).dt.normalize().astype('datetime64[ns]')
    try:
        _out.to_parquet(_ruta, index=False)
    except Exception:
        pass
    return _out


def _clima_rango(desde, hasta):
    """Temperatura de cada comuna entre dos fechas [Fecha, Comuna, T_max, T_min, T_media] y si se pudo bajar todo
    (si el servicio no responde, vacío y False)."""
    _partes, _ok = [], True
    _fallas, _ahora = _clima_fallas(), pd.Timestamp.now()
    for _a in range(pd.Timestamp(desde).year, pd.Timestamp(hasta).year + 1):
        _t = _fallas.get(_a)
        if _t is not None and (_ahora - _t).total_seconds() < 900:
            _ok = False  # falló hace menos de 15 minutos: todavía no se reintenta
            continue
        try:
            _partes.append(_clima_anio(_a))
            _fallas.pop(_a, None)
        except Exception:
            _fallas[_a] = _ahora
            _ok = False
    _partes = [p for p in _partes if not p.empty]
    if not _partes:
        return pd.DataFrame({'Fecha': pd.Series(dtype='datetime64[ns]'), 'Comuna': pd.Series(dtype=object),
                             'T_max': pd.Series(dtype=float), 'T_min': pd.Series(dtype=float), 'T_media': pd.Series(dtype=float)}), _ok
    _c = pd.concat(_partes, ignore_index=True)
    _c['Fecha'] = pd.to_datetime(_c['Fecha']).dt.normalize().astype('datetime64[ns]')
    _c = _c[(_c['Fecha'] >= pd.Timestamp(desde).normalize()) & (_c['Fecha'] <= pd.Timestamp(hasta).normalize())]
    return _c.reset_index(drop=True), _ok


def _clima_linea(clima):
    """Temperatura de la línea por día: promedio de las comunas ponderado por los km de línea en cada una."""
    if clima is None or clima.empty:
        return pd.DataFrame({'Fecha': pd.Series(dtype='datetime64[ns]'), 'T_max_linea': pd.Series(dtype=float),
                             'T_min_linea': pd.Series(dtype=float), 'T_media_linea': pd.Series(dtype=float)})
    _c = clima.assign(_w=clima['Comuna'].map(_peso_comunas()))
    _f = lambda col: (_c[col] * _c['_w']).groupby(_c['Fecha']).sum() / _c['_w'].where(_c[col].notna()).groupby(_c['Fecha']).sum()
    _out = pd.DataFrame({'T_max_linea': _f('T_max'), 'T_min_linea': _f('T_min'), 'T_media_linea': _f('T_media')}).round(1)
    _out.index.name = 'Fecha'
    return _out.reset_index()


def _clima_ancho(clima, valores=('T_max', 'T_min', 'T_media'), unidad='[°C]'):
    """Una columna por comuna y dato (T máx., T mín., T media) y una fila por fecha, en el orden de la línea."""
    _nom = {'T_max': 'T máx.', 'T_min': 'T mín.', 'T_media': 'T media'}
    if clima is None or clima.empty:
        return pd.DataFrame({'Fecha': pd.Series(dtype='datetime64[ns]')})
    _pv = clima.pivot_table(index='Fecha', columns='Comuna', values=list(valores), aggfunc='mean')
    _ord = [(t, c) for c in _COMUNAS_LINEA for t in valores if (t, c) in _pv.columns]
    _pv = _pv[_ord]
    _pv.columns = [f"{_nom[t]} {c} {unidad}" for t, c in _ord]
    return _pv.reset_index()


# Pasajeros-km por día de la Carga de pasajeros (la usan 🌌 Dashboard, 📏 Línea base y causa raíz)
def _paxkm_por_dia(df):
    """PAX-km/día = Σ_viajes Σ_tramos (pasajeros a bordo × km del tramo).

    Lee las columnas de estaciones en el orden real del export de Carga (V1 o V2).
    El km del tramo es la distancia absoluta entre estaciones consecutivas,
    y los pasajeros corresponden a los que viajan ENTRE esas estaciones.
    No se multiplica el total diario de pasajeros por el odómetro de la flota:
    ese producto no representa los kilómetros efectivamente transportados.
    """
    if df is None or getattr(df, 'empty', True) or 'Fecha' not in df.columns:
        return pd.Series(dtype=float)
    # Mantener el orden de las estaciones del archivo: V2 puede ir invertida.
    _kmc = {PAX_COL_CODE[_e]: _KM_ESTACION[_norm(_e)]
            for _e in ESTACIONES if _norm(_e) in _KM_ESTACION}
    _cods = [c for c in df.columns if c in _kmc]
    if len(_cods) < 2:
        return pd.Series(dtype=float)
    _fechas = pd.to_datetime(df['Fecha'], errors='coerce').dt.normalize()
    _pax = df[_cods].apply(pd.to_numeric, errors='coerce').fillna(0).clip(lower=0).to_numpy(dtype=float)
    _km_est = np.array([_kmc[c] for c in _cods], dtype=float)
    _km_tramo = np.abs(np.diff(_km_est))
    # La carga de una estación describe los pasajeros a bordo para el
    # recorrido hasta la siguiente estación; la última no tiene tramo saliente.
    _pax_km_tramo = _pax[:, :-1] * _km_tramo[None, :]
    _pax_km_viaje = _pax_km_tramo.sum(axis=1)
    _serie = pd.Series(_pax_km_viaje, index=_fechas)
    _serie = _serie[_serie.index.notna()]
    return _serie.groupby(level=0).sum().sort_index()


def _cargar_archivos_sin_interrumpir(_archivos, _lector, _tipo, _inicio, _fin, _errores):
    """Continúa procesando los demás archivos aunque uno falle."""
    _procesados = []
    for _f in _archivos:
        try:
            _dato = _lector(_f, _inicio, _fin)
            if _dato is not None:
                _procesados.append(_dato)
        except Exception as _exc:
            _errores[getattr(_f, 'name', 'archivo sin nombre')] = f"{_tipo}: {_exc}"
        finally:
            # v27: cada archivo se lee una vez, y se libera su buffer Excel.
            if '_v27_avanzar' in globals() and '_v27_progreso' in globals():
                _v27_avanzar(_tipo)
            if '_v27_soltar_archivo' in globals():
                _v27_soltar_archivo(_f)
    return _procesados


