def _v29_necesarios():
    _idx = _SECCIONES.index(_seccion)
    # Datos comunes para el filtro global y para toda la navegación.
    _claves = {'df_ops', *(_V29_DATOS_POR_SECCION[_idx])}
    # Detalle THDR de BI a demanda; evita reservar RAM de miles de servicios
    # cuando sólo se consulta el resumen ejecutivo.
    if _seccion == '🎯 BI Ejecutivo' and st.session_state.get('_bi_detalle_thdr', False):
        _claves.update(('df_thdr_v1', 'df_thdr_v2'))
    return _claves


def _v29_archivo_local(_manifest):
    """Construye un ZIP validado por SHA sin concatenarlo en BytesIO."""
    _V28_DIR.mkdir(parents=True, exist_ok=True)
    _local = _V28_DIR / ('local_' + _manifest['source_sha256'][:16] + '_'
                           + _manifest['code_sha256'][:10] + '.zip')
    _largo = sum(int(_p['bytes']) for _p in _manifest['parts'])
    if _local.is_file() and _local.stat().st_size == _largo:
        return _local
    # Archivos temporales únicos para dos visitantes que entren simultáneamente.
    _fd, _ruta_tmp = _v28_tempfile.mkstemp(prefix='.historial-v29-', suffix='.tmp', dir=_V28_DIR)
    os.close(_fd)
    _tmp = _V28Path(_ruta_tmp)
    try:
        with _tmp.open('wb') as _salida:
            for _part in _manifest['parts']:
                _nombre = _part['name']
                if not re.fullmatch(r'historial_\d{3}\.part', _nombre):
                    raise ValueError('Segmento de historial con nombre inválido')
                _h = hashlib.sha256()
                _l = 0
                with (_V28_DIR / _nombre).open('rb') as _entrada:
                    for _buf in iter(lambda: _entrada.read(1024 * 1024), b''):
                        _h.update(_buf)
                        _l += len(_buf)
                        _salida.write(_buf)
                if _l != _part['bytes'] or _h.hexdigest() != _part['sha256']:
                    raise ValueError('Segmento del historial dañado: '+_nombre)
        if _tmp.stat().st_size != _largo:
            raise ValueError('El ZIP histórico está incompleto')
        os.replace(_tmp, _local)
    finally:
        if _tmp.exists():
            _tmp.unlink()
    return _local


def _v28_recuperar_snapshot(_firma, _claves=None):
    """Recupera solo las tablas que necesita la sección visible.

    No reconstruye los 1.215 Excel ni mantiene en memoria las tablas de todas
    las secciones simultáneamente. El histórico sigue almacenado en GitHub.
    """
    _ruta = _V28_DIR / 'manifest.json'
    if not _ruta.is_file():
        return False
    try:
        _m = _v28_json.loads(_ruta.read_text(encoding='utf-8'))
        _actual = _v28_firma_codigo()
        _compat = _V29_CODIGOS_COMPATIBLES if os.getenv('OP_CACHE_BUILD') != '1' else set()
        if (_m.get('schema') != _V28_SCHEMA or _m.get('source_sha256') != _firma
                or _m.get('code_sha256') not in ({_actual} | _compat)):
            return False
        st.session_state['_bi_snapshot_sfe_antiguo'] = (_m.get('code_sha256') != _actual)
        _solicitadas = set(_V28_KEYS if _claves is None else _claves)
        if 'df_ops' not in _solicitadas:
            _solicitadas.add('df_ops')
        # El snapshot v33 todavía no incluye tiempos THDR precalculados.
        # Lo omite temporalmente y mantiene el BI online mientras Actions genera v34.
        if 'df_bi_tiempos' not in _m['types']:
            _solicitadas.discard('df_bi_tiempos')
            st.session_state.pop('df_bi_tiempos',None)
        _faltantes = _solicitadas - set(_m['types'])
        if _faltantes:
            raise ValueError('Faltan tablas en el historial: '+', '.join(sorted(_faltantes)))
        _zip_local = _v29_archivo_local(_m)
        _recuperados = {}
        _mismas_fuentes = st.session_state.get('_v29_firma_restaurada') == _firma
        with _v28_zipfile.ZipFile(_zip_local, 'r') as _zip:
            _necesarios_zip = {
                _key + ('.parquet' if _m['types'][_key] in ('frame', 'records') else '.json')
                for _key in _solicitadas
            }
            if not _necesarios_zip.issubset(set(_zip.namelist())):
                raise ValueError('El historial publicado no contiene todas las tablas requeridas')
            # Soltar las tablas anteriores ANTES de cargar las nuevas reduce el pico de RAM.
            if os.getenv('OP_CACHE_BUILD') != '1':
                for _vieja in _V28_KEYS:
                    if _vieja not in _solicitadas:
                        st.session_state.pop(_vieja, None)
            for _key in _V28_KEYS:
                if _key in _solicitadas and not (_mismas_fuentes and _key in st.session_state):
                    _recuperados[_key] = _v28_leer_valor(_zip, _key, _m['types'][_key])
        st.session_state.update(_recuperados)
        st.session_state['_v29_firma_restaurada'] = _firma
        if 'df_oit' in st.session_state:
            st.session_state['df_oit'].attrs['diag'] = st.session_state.get('_oit_diag', {})
        st.session_state['_v28_recuperado'] = True
        st.session_state['_v29_seccion_recuperada'] = _SECCIONES.index(_seccion)
        st.session_state['_historial_archivos_procesados'] = _m.get('source_files', 0)
        _ops = st.session_state['df_ops']
        if not _ops.empty and 'Fecha' in _ops:
            _fechas = pd.to_datetime(_ops['Fecha'], errors='coerce').dropna()
            if not _fechas.empty:
                st.session_state['_historial_fecha_inicio'] = _fechas.min().date()
                st.session_state['_historial_fecha_fin'] = _fechas.max().date()
        st.session_state['_v28_creado_utc'] = _m.get('created_utc')
        st.session_state.pop('_v28_error_recuperacion', None)
        return True
    except Exception as _exc:
        st.session_state['_v28_error_recuperacion'] = str(_exc)[:500]
        return False


# ===== v30 · CONTROL DE ACCESO POR PERFILES =====
# Credenciales exclusivamente en Streamlit Secrets (NO en GitHub).
# Sin configuración, panel en modo consulta: las cargas/borrados quedan bloqueados.
import hmac as _bi_hmac

_BI_ROLES = ('lector', 'analista', 'admin')

def _bi_validar_clave(_clave, _usuario):
    """PBKDF2-HMAC-SHA256; compara hash en tiempo constante."""
    try:
        _salt = bytes.fromhex(str(_usuario['salt_hex']))
        _esperado = bytes.fromhex(str(_usuario['password_hash_hex']))
        _n = int(_usuario.get('iterations', 390000))
        if len(_salt) < 16 or len(_esperado) != 32 or _n < 200000 or _n > 2000000:
            return False
        _calculado = hashlib.pbkdf2_hmac('sha256', _clave.encode('utf-8'), _salt, _n)
        return _bi_hmac.compare_digest(_calculado, _esperado)
    except (ValueError, KeyError, TypeError, AttributeError):
        return False


def _bi_configuracion():
    try:
        _conf = st.secrets.get('bi_access', {})
        return _conf if hasattr(_conf, 'get') and _conf.get('enabled', False) else None
    except Exception:
        return None


def _bi_autenticar():
    # El runner de GitHub Actions no es un visitante de la web; debe poder
    # construir el historial aun sin Secrets ni sesión autenticada.
    if os.getenv('OP_CACHE_BUILD') == '1':
        return 'admin', 'GitHub Actions'
    _cfg = _bi_configuracion()
    if _cfg is None:
        st.sidebar.caption('🔓 Acceso de consulta abierto · administración bloqueada')
        return 'lector', 'Consulta pública'
    _usuarios = _cfg.get('users', [])
    if not isinstance(_usuarios, (list, tuple)) or not _usuarios:
        st.error('El control de acceso está activado, pero no hay usuarios válidos configurados.')
        st.stop()
    _cuentas = {str(u.get('username', '')).strip().casefold(): u
                for u in _usuarios if hasattr(u, 'get') and u.get('username')}
    _activo = st.session_state.get('_bi_usuario')
    if _activo and _activo in _cuentas:
        _rol = str(_cuentas[_activo].get('role', 'lector')).lower()
        _identidad = hashlib.sha256(
            (_rol + ':' + str(_cuentas[_activo].get('password_hash_hex',''))).encode()
        ).hexdigest()
        if _rol in _BI_ROLES and st.session_state.get('_bi_identidad') == _identidad:
            st.sidebar.caption(f'🔒 {_activo} · {_rol}')
            if st.sidebar.button('Cerrar sesión', key='_bi_salir'):
                for _key in ('_bi_usuario', '_bi_identidad', '_bi_detalle_thdr', '_nav_seccion'):
                    st.session_state.pop(_key, None)
                st.rerun()
            return _rol, _activo
    st.sidebar.markdown('### 🔒 Acceso al BI')
    with st.sidebar.form('_bi_form_ingreso',clear_on_submit=True):
        _nombre = st.text_input('Usuario', key='_bi_login_user')
        _clave = st.text_input('Contraseña', type='password', key='_bi_login_pwd')
        _enviar = st.form_submit_button('Ingresar', use_container_width=True)
    if _enviar:
        _ident = _nombre.strip().casefold()
        _cuenta = _cuentas.get(_ident)
        if _cuenta and _bi_validar_clave(_clave, _cuenta):
            st.session_state['_bi_usuario'] = _ident
            _rol = str(_cuenta.get('role','lector')).lower()
            st.session_state['_bi_identidad'] = hashlib.sha256(
                (_rol + ':' + str(_cuenta.get('password_hash_hex',''))).encode()
            ).hexdigest()
            st.rerun()
        st.sidebar.error('Usuario o contraseña incorrectos.')
    st.info('Inicia sesión con un usuario autorizado para consultar este BI.')
    st.stop()

_BI_ROL_ACTUAL, _BI_USUARIO_ACTUAL = _bi_autenticar()
