# ===== v30 · INTELIGENCIA DE NEGOCIOS OPERACIONAL =====
# Sección adicional: no modifica las 14 vistas históricas ni los cálculos fuente.
def _bi_serie(df, nombre):
    if nombre in df.columns:
        return pd.to_numeric(df[nombre], errors='coerce')
    return pd.Series(np.nan, index=df.index, dtype='float64')


def _bi_base_liviana(tabla):
    """Serie diaria de KPI: conserva NaN para ausencia, no inventa observaciones."""
    _nombres = ['E_Total', 'E_Tr', 'E_12', 'Odómetro [km]',
                'Tren-Km [km]', 'PAX', 'Servicios', 'IDE (kWh/km)', 'UMR (%)',
                'E_Fact', 'E_Prmte', 'E_Seat_T', 'E_Seat_Tr', 'E_Seat_12',
                '% Tracción', '% 12 kV']
    if tabla is None or getattr(tabla, 'empty', True) or 'Fecha' not in tabla.columns:
        return pd.DataFrame(columns=['Fecha'] + _nombres)
    _out = pd.DataFrame({'Fecha':pd.to_datetime(tabla['Fecha'], errors='coerce').dt.normalize()})
    for _col in _nombres:
        _out[_col] = _bi_serie(tabla, _col)
    if 'Fuente' in tabla.columns:
        _out['Fuente'] = tabla['Fuente'].astype(str).to_numpy()
    # Una única clasificación chilena para filtros, KPI, alertas, pronósticos y detalle.
    # Un festivo en sábado o en día hábil SIEMPRE es D/F, no S ni L.
    _out = _out.dropna(subset=['Fecha']).sort_values('Fecha').reset_index(drop=True)
    _out['Tipo Día'] = _out['Fecha'].dt.date.map(get_tipo_dia)
    _out['Tipo de jornada'] = _out['Tipo Día'].map(_JORNADA_TXT)
    _out['Etapa SFE'] = _out['Fecha'].map(_sfe_fase)
    _out['SFE habilitados comercialmente'] = _out['Etapa SFE'].map({
        _SFE_ETAPAS[0]:0,_SFE_ETAPAS[1]:1,_SFE_ETAPAS[2]:3})
    return _out


# ===== v31 · Comparaciones homogéneas por jornada (Chile) =====
def _bi_referencia_comparable(historico, visible):
    """Devuelve N días anteriores de la MISMA jornada por cada clase presente.

    Si no hay suficientes días anteriores equivalentes para CADA tipo visible,
    se omite el delta. Nunca sustituimos sábados por domingos/festivos, ni viceversa.
    """
    if historico is None or visible is None or historico.empty or visible.empty:
        return pd.DataFrame(), False
    _inicio = visible['Fecha'].min()
    _previos = historico[historico['Fecha'] < _inicio].sort_values('Fecha')
    _trozos = []
    _claves=['Tipo Día']+(['Etapa SFE'] if 'Etapa SFE' in visible and 'Etapa SFE' in historico else [])
    for _grupo_id, _grupo in visible.groupby(_claves, observed=True):
        _cantidad = int(_grupo['Fecha'].nunique())
        _mismos = _previos[_previos['Tipo Día'] == _grupo['Tipo Día'].iloc[0]]
        if 'Etapa SFE' in _claves:
            _mismos = _mismos[_mismos['Etapa SFE'] == _grupo['Etapa SFE'].iloc[0]]
        _mismos = _mismos.drop_duplicates('Fecha', keep='last')
        if len(_mismos) < _cantidad:
            return pd.DataFrame(columns=historico.columns), False
        _trozos.append(_mismos.tail(_cantidad))
    if not _trozos:
        return pd.DataFrame(columns=historico.columns), False
    return pd.concat(_trozos, ignore_index=True).sort_values('Fecha'), True


def _bi_resumen_por_jornada(visible):
    """Totales por jornada sin mezclar tipos en promedios ni IDE ponderado."""
    _r=[]
    for _tipo, _nombre in [('L','Laboral'),('S','Sábado'),('D/F','Domingo y festivo')]:
        _m = visible[visible['Tipo Día'] == _tipo]
        if _m.empty:
            continue
        _dias = int(_m['Fecha'].nunique())
        _energia = _bi_valor_kpi(_m, 'E_Total')
        _km = _bi_valor_kpi(_m, 'Odómetro [km]')
        _pax = _bi_valor_kpi(_m, 'PAX')
        _serv = _bi_valor_kpi(_m, 'Servicios')
        _ide = _bi_valor_kpi(_m, 'IDE (kWh/km)')
        _r.append({'Tipo de jornada': _nombre, 'Días':_dias,
                   'Energía (kWh)':_energia, 'Energía por día (kWh)':_energia/_dias if np.isfinite(_energia) else np.nan,
                   'Kilómetros':_km,
                   'Kilómetros por día':_km/_dias if np.isfinite(_km) else np.nan,
                   'Pasajeros':_pax, 'Pasajeros por día':_pax/_dias if np.isfinite(_pax) else np.nan,
                   'Servicios':_serv, 'Servicios por día':_serv/_dias if np.isfinite(_serv) else np.nan,
                   'Tracción por día (kWh)': _bi_valor_kpi(_m,'E_Tr')/_dias,
                   'IDE (kWh/km)':_ide})
    return pd.DataFrame(_r)



# ===== v32 · Unión por fecha entre BI diario y OIT de madrugada =====
# IMPORTANTE: OIT registra ORDENES SFE CON CIERRE entre 00:00 y 06:59.
# La fecha es la del CIERRE (madrugada) y no necesariamente el instante del
# movimiento real. No se transforma una orden en un viaje/servicio realizado.
def _bi_unicos_noche(valores, limite=12):
    """Conserva valores distintos de una noche en orden de aparición."""
    _vistos = set()
    _texto = []
    for _valor in valores:
        if pd.isna(_valor):
            continue
        _t = str(_valor).strip()
        if not _t or _t.casefold() in ('nan', 'none', 'nat', 'sin dato'):
            continue
        if _t not in _vistos:
            _vistos.add(_t)
            _texto.append(_t)
        if len(_texto) >= limite:
            break
    return ' · '.join(_texto)


def _bi_cruzar_nocturnos(diario, oit, hay_fuente_oit):
    """Una fila por día. Las OIT nunca duplican los kWh o los servicios.

    'Sin orden detectada' no significa 'sin movimiento': hay fechas sin OIT o
    fuera de la cobertura de los exportes y el parser sólo detecta cierres SFE.
    """
    if diario is None or diario.empty:
        return pd.DataFrame()
    _base = diario.copy()
    _base['Fecha'] = pd.to_datetime(_base['Fecha'], errors='coerce').dt.normalize()
    _base = _base.dropna(subset=['Fecha'])
    _base['Órdenes OIT madrugada'] = 0
    _base['Unidades SFE OIT'] = ''
    _base['Horas cierre OIT'] = ''
    _base['OT nocturnas'] = ''
    _base['Trabajos OIT'] = ''
    if oit is not None and not oit.empty and 'Fecha' in oit.columns:
        _e = oit.copy()
        _e['Fecha'] = pd.to_datetime(_e['Fecha'], errors='coerce').dt.normalize()
        _e = _e.dropna(subset=['Fecha']).drop_duplicates()
        for _c in ('SFE','Hora cierre','OT','Trabajos'):
            if _c not in _e.columns:
                _e[_c] = ''
        if not _e.empty:
            _g = _e.groupby('Fecha',as_index=False).agg(**{
                '_ordenes': ('Fecha','size'),
                '_sfe': ('SFE',_bi_unicos_noche),
                '_horas': ('Hora cierre',_bi_unicos_noche),
                '_ots': ('OT',_bi_unicos_noche),
                '_trabajos': ('Trabajos',_bi_unicos_noche),
            })
            _base = _base.merge(_g,on='Fecha',how='left',validate='many_to_one',sort=False)
            _base['Órdenes OIT madrugada'] = _base['_ordenes'].fillna(0).astype(int)
            for _column,_src in [('Unidades SFE OIT','_sfe'),('Horas cierre OIT','_horas'),
                                 ('OT nocturnas','_ots'),('Trabajos OIT','_trabajos')]:
                _base[_column] = _base[_src].fillna('')
            _base = _base.drop(columns=['_ordenes','_sfe','_horas','_ots','_trabajos'])
    _base['Registro OIT nocturno'] = np.where(
        _base['Órdenes OIT madrugada'].gt(0), 'Con orden SFE de madrugada',
        'Sin orden SFE detectada' if hay_fuente_oit else 'Sin archivos OIT')
    return _base


def _bi_resumen_nocturno_por_jornada(diario):
    """Resumen descriptivo, separado por jornada y presencia de OIT.
    Los promedios nunca cuentan dos veces un día con varias órdenes.
    """
    _cols=['Tipo de jornada','Registro OIT nocturno','Días','Órdenes OIT',
           'Energía media diaria (kWh)','Tracción media diaria (kWh)',
           'Kilómetros medios diarios','IDE ponderado (kWh/km)']
    if diario is None or diario.empty:
        return pd.DataFrame(columns=_cols)
    _datos=[]
    for (_j,_s),_v in diario.groupby(['Tipo de jornada','Registro OIT nocturno'],dropna=False,observed=True):
        _n = int(_v['Fecha'].nunique())
        _en = pd.to_numeric(_v['E_Total'],errors='coerce')
        _tr = pd.to_numeric(_v['E_Tr'],errors='coerce')
        _km = pd.to_numeric(_v['Odómetro [km]'],errors='coerce')
        _t = float(_tr.sum(min_count=1)) if _tr.notna().any() else np.nan
        _k = float(_km.sum(min_count=1)) if _km.notna().any() else np.nan
        _datos.append({'Tipo de jornada':_j, 'Registro OIT nocturno':_s,'Días':_n,
                       'Órdenes OIT':int(_v['Órdenes OIT madrugada'].sum()),
                       'Energía media diaria (kWh)':float(_en.mean()) if _en.notna().any() else np.nan,
                       'Tracción media diaria (kWh)':float(_tr.mean()) if _tr.notna().any() else np.nan,
                       'Kilómetros medios diarios':float(_km.mean()) if _km.notna().any() else np.nan,
                       'IDE ponderado (kWh/km)':_t/_k if pd.notna(_k) and _k>0 and pd.notna(_t) else np.nan})
    _ord={'Laboral':0,'Sábado':1,'Domingo y festivo':2}
    _salida=pd.DataFrame(_datos,columns=_cols)
    return _salida.sort_values('Tipo de jornada',key=lambda x:x.map(_ord)).reset_index(drop=True)


def _bi_comparar_con_sin_oit(diario, minimo=3):
    """Diferencia exploratoria de MEDIANAS diarias entre grupos de una MISMA jornada.
    Nunca se interpreta como consumo atribuible a la circulación SFE.
    """
    _cols=['Tipo de jornada','Días con orden OIT','Días sin orden detectada',
           'Mediana con orden (kWh/día)','Mediana sin orden (kWh/día)','Diferencia (kWh/día)']
    if diario is None or diario.empty or 'Órdenes OIT madrugada' not in diario:
        return pd.DataFrame(columns=_cols)
    _rs=[]
    for _j in ('Laboral','Sábado','Domingo y festivo'):
        _d=diario[diario['Tipo de jornada']==_j]
        _con=pd.to_numeric(_d.loc[_d['Órdenes OIT madrugada'].gt(0),'E_Total'],errors='coerce').dropna()
        _sin=pd.to_numeric(_d.loc[_d['Órdenes OIT madrugada'].eq(0),'E_Total'],errors='coerce').dropna()
        if len(_con) < minimo or len(_sin) < minimo:
            continue
        _mc=float(_con.median());_ms=float(_sin.median())
        _rs.append({'Tipo de jornada':_j,'Días con orden OIT':len(_con),
                    'Días sin orden detectada':len(_sin),
                    'Mediana con orden (kWh/día)':_mc,
                    'Mediana sin orden (kWh/día)':_ms,
                    'Diferencia (kWh/día)':_mc-_ms})
    return pd.DataFrame(_rs,columns=_cols)



# ===== v33 · Investigación transversal de días con exceso del IDE =====
# El sobreconsumo OFICIAL DEL MODELO disponible en esta aplicación depende de
# E_LB ajustada = intercepto + c100*km100 + cSFE*kmSFE_comercial
#                 + cSFE*kmSFE_pruebas_pre_alta (solo estimación en línea base).
# En el BI no se atribuye causalidad a incidentes, OIT ni cambios operacionales:
# se presentan coincidencias verificables por FECHA y jornada comparable.

def _bi_ide_km_sfe(registros):
    """Resumen diario UMR (sin conservar todos los registros por tren en el BI)."""
    _cols=['Fecha','Odom_SFE','Odom_SFE_pruebas',
           'Registros UMR km','Registros SFE km','Registros SFE pruebas km']
    if not registros:
        return pd.DataFrame(columns=_cols)
    _r = pd.DataFrame(registros)
    if not {'Fecha','Tren','Valor'}.issubset(_r.columns):
        return pd.DataFrame(columns=_cols)
    _r['Fecha']=pd.to_datetime(_r['Fecha'],errors='coerce').dt.normalize()
    _r['Valor']=pd.to_numeric(_r['Valor'],errors='coerce')
    if 'Clase' in _r and _r['Clase'].notna().any():
        _r=_r[_r['Clase'].astype(str).str.strip().str.casefold().eq('km')].copy()
    else:
        _r=_r[_r['Valor'].lt(50000)].copy()
    _r=_r[_r['Fecha'].notna() & _r['Valor'].ge(0)].copy()
    if _r.empty:
        return pd.DataFrame(columns=_cols)
    _es_sfe=_r['Tren'].astype(str).str.strip().str.upper().str.startswith('SFE')
    _comercial=_es_sfe & _sfe_mascara_comercial(_r['Tren'],_r['Fecha'])
    # Solo SFE-410, 411 y 412 tienen fecha de habilitación verificada.
    # Unidades SFE sin identificación no se estiman: se debe revisar la fuente.
    _identificada=_r['Tren'].map(_sfe_unidad).notna()
    _prueba=_es_sfe & _identificada & ~_comercial
    _r['_sfe']=_r['Valor'].where(_comercial,0.0)
    _r['_sfe_pruebas']=_r['Valor'].where(_prueba,0.0)
    _ids=_r['Tren'].map(_sfe_unidad)
    for _id in ('410','411','412'):
        _r[f'_test_{_id}']=_r['Valor'].where(_prueba & _ids.eq(_id),0.0)
    _r['_es_sfe']=_comercial.astype(int)
    _r['_es_prueba']=_prueba.astype(int)
    _grp=_r.groupby('Fecha',as_index=False).agg(**{
        'Odom_SFE':('_sfe','sum'),
        'Odom_SFE_pruebas':('_sfe_pruebas','sum'),
        'Registros UMR km':('Valor','size'),
        'Registros SFE km':('_es_sfe','sum'),
        'Registros SFE pruebas km':('_es_prueba','sum'),
        **{f'SFE-{_id} km pruebas UMR':(f'_test_{_id}','sum')
           for _id in ('410','411','412')},
    })
    return _grp


def _bi_lb_energia_componentes(tabla):
    """LB diaria trazable. SFE en pruebas se estima SOLO antes de su alta comercial.

    - Commercial 412 desde 22-abr-2026; 410/411 desde 25-sep-2026.
    - E comercial SFE ya entra UNA vez en la línea base ordinaria.
    - Km de pruebas UMR, excluidos de odómetro comercial, añaden solamente
      kWh estimados = km_pruebas * IDE_LB_SFE; nunca se suman al consumo real.
    - Sin UMR/km o coeficientes, no se presume que el estimativo es cero.
    """
    _t=tabla.copy()
    for _c in ('Intercepcion','IDE_LB_100M','IDE_LB_SFE','Odom_SFE',
               'Odom_SFE_pruebas','Registros UMR km','Odómetro [km]'):
        if _c not in _t.columns:
            _t[_c]=np.nan
    _odo=pd.to_numeric(_t['Odómetro [km]'],errors='coerce')
    _com=pd.to_numeric(_t['Odom_SFE'],errors='coerce')
    _pr=pd.to_numeric(_t['Odom_SFE_pruebas'],errors='coerce')
    _odo_100=_odo-_com
    _c0=pd.to_numeric(_t['Intercepcion'],errors='coerce')
    _c100=pd.to_numeric(_t['IDE_LB_100M'],errors='coerce')
    _csfe=pd.to_numeric(_t['IDE_LB_SFE'],errors='coerce')
    _real=(pd.to_numeric(_t['E_real'],errors='coerce') if 'E_real' in _t.columns
           else pd.to_numeric(_t['E_Tr'],errors='coerce') if 'E_Tr' in _t.columns
           else pd.Series(np.nan,index=_t.index))
    _cob=pd.to_numeric(_t['Registros UMR km'],errors='coerce')
    _ok=(_odo.gt(0) & _real.gt(0) & _cob.gt(0) & _com.ge(0) & _pr.ge(0)
         & _odo_100.ge(-0.0001) & _c0.notna() & _c100.ge(0) & _csfe.ge(0))
    _base=_c0 + _c100*_odo_100.clip(lower=0) + _csfe*_com
    _estima=_csfe*_pr
    _total=_base+_estima
    _ok &= _total.gt(0)
    _t['Odom_100M']=_odo_100.where(_ok)
    _t['E_LB_base_sin_pruebas (kWh)']=_base.where(_ok)
    _t['E_SFE_comercial_en_LB (kWh)']=(_csfe*_com).where(_ok)
    _t['E_SFE_pruebas_estimada_LB (kWh)']=_estima.where(_ok)
    # Desglose opcional por unidad: la suma equivale al ajuste total.
    for _id in ('410','411','412'):
        _nombre=f'SFE-{_id} km pruebas UMR'
        if _nombre in _t.columns:
            _pr_id=pd.to_numeric(_t[_nombre],errors='coerce')
            _t[f'E SFE-{_id} estimada pruebas LB (kWh)']=(_csfe*_pr_id).where(_ok)
    _t['E_LB (kWh)']=_total.where(_ok)
    _t['IDE_LB (kWh/km)']=(_total/_odo.where(_odo.gt(0))).where(_ok)
    _t['Exceso LB (kWh)']=(_real-_total).where(_ok)
    _t['Sobreconsumo LB %']=((_real/_total-1)*100).where(_ok)
    _t['Línea base calculable']=_ok
    return _t


def _bi_lb_diaria_desde_umr(diario, lb, registros):
    """Uniforma la LB de Ahorro y Sobreconsumo con Investigación IDE.

    La unión es uno-a-uno por fecha para impedir duplicar la energía.
    """
    if diario is None or diario.empty or lb is None or lb.empty:
        return pd.DataFrame()
    _t=diario.copy()
    _t['Fecha']=pd.to_datetime(_t['Fecha'],errors='coerce').dt.normalize()
    _l=lb[['Fecha','Intercepcion','IDE_LB_100M','IDE_LB_SFE']].copy()
    _l['Fecha']=pd.to_datetime(_l['Fecha'],errors='coerce').dt.normalize()
    _l=_l.dropna(subset=['Fecha']).sort_values('Fecha').drop_duplicates('Fecha',keep='last')
    _t=_t.merge(_l,on='Fecha',how='inner',validate='one_to_one')
    _km=_bi_ide_km_sfe(registros)
    if not _km.empty:
        _t=_t.merge(_km,on='Fecha',how='left',validate='one_to_one')
    _tr=pd.to_numeric(_t['E_Tr'],errors='coerce')
    _ide=pd.to_numeric(_t.get('IDE (kWh/km)',pd.Series(np.nan,index=_t.index)),errors='coerce')
    _odo=pd.to_numeric(_t['Odómetro [km]'],errors='coerce')
    _t['E_real']=_tr.where(_tr.gt(0),_ide*_odo)
    _t=_bi_lb_energia_componentes(_t)
    _t['E_LB']=_t['E_LB (kWh)']
    _t['IDE_LB']=_t['IDE_LB (kWh/km)']
    _t['Desvío']=_ide-_t['IDE_LB']
    _t['Exceso kWh']=_t['Exceso LB (kWh)']
    return _t




# ===== v35 · CRUCE DE FASES COMERCIALES SFE EN BI =====
def _bi_sfe_cruzar(diario, km_agrupado, thdr_compacto=None):
    """Cruce 1:1 por Fecha; THDR es movimiento registrado, no habilitación."""
    _cols=['Fecha','Etapa SFE','SFE habilitados comercialmente',
           'SFE-410 km comercial','SFE-411 km comercial','SFE-412 km comercial',
           'SFE comerciales km UMR','SFE pruebas km UMR',
           'Unidades SFE con km comercial','Viajes SFE THDR comerciales']
    if diario is None or diario.empty: return pd.DataFrame(columns=_cols)
    _d=diario.copy()
    if 'Etapa SFE' not in _d:
        _d['Etapa SFE']=_d['Fecha'].map(_sfe_fase)
    if 'SFE habilitados comercialmente' not in _d:
        _d['SFE habilitados comercialmente']=_d['Etapa SFE'].map({
            _SFE_ETAPAS[0]:0,_SFE_ETAPAS[1]:1,_SFE_ETAPAS[2]:3})
    if km_agrupado is not None and not km_agrupado.empty:
        _d=_d.merge(km_agrupado,on='Fecha',how='left',validate='one_to_one')
    else:
        for _c in ['SFE-410 km comercial','SFE-411 km comercial','SFE-412 km comercial',
                   'SFE comerciales km UMR','SFE pruebas km UMR','Unidades SFE con km comercial']:
            _d[_c]=np.nan
    _d['Viajes SFE THDR comerciales']=np.nan
    if thdr_compacto is not None and not thdr_compacto.empty:
        if {'Fecha','Unidad SFE','SFE comercial registrado THDR'}.issubset(thdr_compacto.columns):
            _t=thdr_compacto.copy()
            _t['Fecha']=pd.to_datetime(_t['Fecha'],errors='coerce').dt.normalize()
            _x=_t[_t['SFE comercial registrado THDR'].fillna(False).astype(bool) & _t['Unidad SFE'].ne('')]
            _counts=_x.groupby('Fecha').size()
            _d['Viajes SFE THDR comerciales']=_d['Fecha'].map(_counts).fillna(0).astype(int)
    return _d

def _bi_ide_referencias(diario, linea_base, kms_sfe, ventana=45, minimo=10):
    """Fecha única, modelo LB 100/M-SFE y referencia histórica anterior de misma jornada.

    IDE inválido si falta energía de tracción u odómetro; NaN no equivale a 0.
    El modelo LB exige cobertura UMR para distinguir cero SFE de sin registros.
    """
    if diario is None or diario.empty or 'Fecha' not in diario:
        return pd.DataFrame()
    _t=diario.copy()
    _t['Fecha']=pd.to_datetime(_t['Fecha'],errors='coerce').dt.normalize()
    _t=_t.dropna(subset=['Fecha']).sort_values('Fecha').drop_duplicates('Fecha',keep='last').reset_index(drop=True)
    _tr=pd.to_numeric(_t['E_Tr'],errors='coerce')
    _km=pd.to_numeric(_t['Odómetro [km]'],errors='coerce')
    _valida = _tr.gt(0) & _km.gt(0)
    _t['IDE real (kWh/km)']=(_tr / _km.where(_km.gt(0))).where(_valida)
    _ide=_t['IDE real (kWh/km)']
    _t['Etapa SFE']=_t['Fecha'].map(_sfe_fase)
    _gb=_ide.groupby([_t['Tipo Día'],_t['Etapa SFE']],sort=False)
    _t['Días previos comparables']=_gb.transform(
        lambda v:v.shift(1).rolling(ventana,min_periods=1).count()).fillna(0).astype(int)
    _t['IDE referencia histórica']=_gb.transform(
        lambda v:v.shift(1).rolling(ventana,min_periods=minimo).median())
    _ref=_t['IDE referencia histórica']
    _t['Desviación histórica %']=((_ide/_ref-1)*100).where(_ref.gt(0))

    _t['Intercepcion']=np.nan
    _t['IDE_LB_100M']=np.nan
    _t['IDE_LB_SFE']=np.nan
    _t['Odom_SFE']=np.nan
    _t['Odom_SFE_pruebas']=np.nan
    _t['Registros UMR km']=np.nan
    _t['Registros SFE km']=np.nan
    _t['Registros SFE pruebas km']=np.nan
    if linea_base is not None and not linea_base.empty and 'Fecha' in linea_base:
        _cols=['Intercepcion','IDE_LB_100M','IDE_LB_SFE']
        if all(c in linea_base.columns for c in _cols):
            _lb=linea_base[['Fecha']+_cols].copy()
            _lb['Fecha']=pd.to_datetime(_lb['Fecha'],errors='coerce').dt.normalize()
            _lb=_lb.dropna(subset=['Fecha']).sort_values('Fecha').drop_duplicates('Fecha',keep='last')
            _t=_t.drop(columns=_cols).merge(_lb,on='Fecha',how='left',validate='one_to_one')
    _kmcols=['Odom_SFE','Odom_SFE_pruebas','Registros UMR km','Registros SFE km',
             'Registros SFE pruebas km']+[f'SFE-{_id} km pruebas UMR' for _id in ('410','411','412')]
    if kms_sfe is not None and not kms_sfe.empty and 'Fecha' in kms_sfe:
        _s=kms_sfe[['Fecha']+[c for c in _kmcols if c in kms_sfe]].copy()
        _s['Fecha']=pd.to_datetime(_s['Fecha'],errors='coerce').dt.normalize()
        _s=_s.dropna(subset=['Fecha']).drop_duplicates('Fecha',keep='last')
        _t=_t.drop(columns=_kmcols,errors='ignore').merge(_s,on='Fecha',how='left',validate='one_to_one')
        for _c in _kmcols:
            if _c not in _t:_t[_c]=np.nan
    # El estimativo de tracción SFE en pruebas se incorpora a energía LB,
    # nunca al consumo real; los km SFE comerciales se contabilizan solo una vez.
    _t=_bi_lb_energia_componentes(_t)
    _t['IDE válido']=_valida
    return _t


def _bi_ide_cruzar_fuentes(tabla, inc_full=None, inc_acoples=None, servicios=None, pax_rutas=None, tiempos=None):
    """Incorpora evidencia diaria sin multiplicar las filas de energía/IDE."""
    if tabla is None or tabla.empty:
        return pd.DataFrame()
    _d=tabla.copy()
    _d['Fecha']=pd.to_datetime(_d['Fecha'],errors='coerce').dt.normalize()
    if _d['Fecha'].duplicated().any():
        raise ValueError('El BI IDE requiere una sola fila por fecha, no una por evento')
    if 'Órdenes OIT madrugada' in _d:
        _dia_siguiente=_d.set_index('Fecha')['Órdenes OIT madrugada']
        _d['OIT cierre madrugada siguiente']=(_d['Fecha']+pd.Timedelta(days=1)).map(_dia_siguiente)
        if 'Registro OIT nocturno' in _d and _d['Registro OIT nocturno'].eq('Sin archivos OIT').all():
            _d['OIT cierre madrugada siguiente']=np.nan
        else:
            _d['OIT cierre madrugada siguiente']=_d['OIT cierre madrugada siguiente'].fillna(0).astype(int)

    if inc_full is not None and not inc_full.empty and 'Fecha' in inc_full:
        _i=inc_full.copy()
        _i['Fecha']=pd.to_datetime(_i['Fecha'],errors='coerce').dt.normalize()
        _i=_i.dropna(subset=['Fecha']).drop_duplicates()
        _i['_afecta']=_i.get('Afecta operación',pd.Series(False,index=_i.index)).fillna(False).astype(bool).astype(int)
        _i['_minutos']=pd.to_numeric(_i.get('Tiempo impacto (min)',pd.Series(np.nan,index=_i.index)),errors='coerce')
        _i=_i.groupby('Fecha',as_index=False).agg(**{
            'Incidentes PCC':('Fecha','size'),
            'Incidentes con afectación':('_afecta','sum'),
            'Minutos de impacto registrados':('_minutos','sum')})
        _d=_d.merge(_i,on='Fecha',how='left',validate='one_to_one')
        for _col in ['Incidentes PCC','Incidentes con afectación']:
            _d[_col]=_d[_col].fillna(0).astype(int)
    else:
        for _col in ['Incidentes PCC','Incidentes con afectación','Minutos de impacto registrados']:
            _d[_col]=np.nan
    if inc_acoples is not None and not inc_acoples.empty and {'Fecha','Tipo'}.issubset(inc_acoples.columns):
        _i=inc_acoples.copy()
        _i['Fecha']=pd.to_datetime(_i['Fecha'],errors='coerce').dt.normalize()
        _i=_i.dropna(subset=['Fecha']).drop_duplicates()
        _i['_acople']=_i['Tipo'].astype(str).str.strip().eq('Acople').astype(int)
        _i['_desacople']=_i['Tipo'].astype(str).str.strip().eq('Desacople').astype(int)
        _i=_i.groupby('Fecha',as_index=False)[['_acople','_desacople']].sum().rename(columns={
            '_acople':'Acoples registrados','_desacople':'Desacoples registrados'})
        _d=_d.merge(_i,on='Fecha',how='left',validate='one_to_one')
        _d[['Acoples registrados','Desacoples registrados']]=_d[['Acoples registrados','Desacoples registrados']].fillna(0).astype(int)
    else:
        _d['Acoples registrados']=np.nan
        _d['Desacoples registrados']=np.nan
    if servicios is not None and not servicios.empty and {'Fecha','Servicios'}.issubset(servicios.columns):
        _s=servicios.copy()
        _s['Fecha']=pd.to_datetime(_s['Fecha'],errors='coerce').dt.normalize()
        _s['Servicios']=pd.to_numeric(_s['Servicios'],errors='coerce')
        _g=_s.groupby('Fecha',as_index=False)['Servicios'].sum(min_count=1).rename(columns={'Servicios':'Servicios THDR por recorrido'})
        _d=_d.merge(_g,on='Fecha',how='left',validate='one_to_one')
    else:
        _d['Servicios THDR por recorrido']=np.nan
    if pax_rutas is not None and not pax_rutas.empty and {'Fecha','PAX'}.issubset(pax_rutas.columns):
        _p=pax_rutas.copy()
        _p['Fecha']=pd.to_datetime(_p['Fecha'],errors='coerce').dt.normalize()
        _p['PAX']=pd.to_numeric(_p['PAX'],errors='coerce')
        _g=_p.groupby('Fecha',as_index=False)['PAX'].sum(min_count=1).rename(columns={'PAX':'Pasajeros asociados a recorridos'})
        _d=_d.merge(_g,on='Fecha',how='left',validate='one_to_one')
    else:
        _d['Pasajeros asociados a recorridos']=np.nan
    # THDR preagregado: una fila por fecha, NO una por tren o estación.
    if tiempos is not None and not tiempos.empty and 'Fecha' in tiempos:
        _tv=tiempos.copy()
        _tv['Fecha']=pd.to_datetime(_tv['Fecha'],errors='coerce').dt.normalize()
        if _tv['Fecha'].duplicated().any():
            raise ValueError('Tiempos THDR deben tener una fila por fecha')
        _d=_d.merge(_tv,on='Fecha',how='left',validate='one_to_one')
    return _d


def _bi_ide_factores_dia(historico, fecha, ventana=45, minimo=5):
    """Variaciones descriptivas contra hasta 45 días anteriores de igual jornada.
    El ranking de valores absolutos NO equivale a impacto causal en IDE.
    """
    _cols=['Indicador','Día investigado','Mediana comparable','Variación %','Antecedentes','Señal']
    if historico is None or historico.empty:
        return pd.DataFrame(columns=_cols)
    _d=pd.Timestamp(fecha).normalize()
    _h=historico.copy()
    _h['Fecha']=pd.to_datetime(_h['Fecha'],errors='coerce').dt.normalize()
    _fila=_h[_h['Fecha'].eq(_d)]
    if _fila.empty:
        return pd.DataFrame(columns=_cols)
    _tipo=_fila.iloc[0].get('Tipo Día')
    _pasado=_h[(_h['Fecha']<_d) & (_h['Tipo Día']==_tipo)].sort_values('Fecha')
    if 'Etapa SFE' in _h:
        _pasado=_pasado[_pasado['Etapa SFE']==_fila.iloc[0]['Etapa SFE']]
    _pasado=_pasado.tail(ventana)
    _indicadores=[('E_Tr','Energía de tracción (kWh)'),('Odómetro [km]','Kilometraje real (km)'),
                  ('E_Total','Energía total (kWh)'),('E_12','Energía 12 kV (kWh)'),
                  ('Tren-Km [km]','Tren-km (km)'),('UMR (%)','Utilización UMR (%)'),
                  ('Servicios','Servicios'),('PAX','Pasajeros'),
                  ('Incidentes PCC','Incidentes PCC'),('Incidentes con afectación','Incidentes con afectación'),
                  ('Órdenes OIT madrugada','Órdenes OIT de madrugada'),
                  ('OIT cierre madrugada siguiente','OIT cierre madrugada siguiente'),
                  ('Desvío tiempo comparable (%)','Desvío del tiempo de viaje por OD (%)'),
                  ('Viajes con referencia','Viajes THDR comparables')]
    _rs=[]
    for _campo,_label in _indicadores:
        if _campo not in _h:
            continue
        _v=pd.to_numeric(pd.Series([_fila.iloc[0].get(_campo)]),errors='coerce').iloc[0]
        _prev=pd.to_numeric(_pasado[_campo],errors='coerce')
        _prev=_prev[_prev.notna()]
        if pd.isna(_v):
            continue
        _n=len(_prev)
        _ref=float(_prev.median()) if _n >= minimo else np.nan
        _dif=100*(_v/_ref-1) if pd.notna(_ref) and _ref>0 else np.nan
        if pd.isna(_ref):
            _senal='Sin historial suficiente'
        elif pd.isna(_dif):
            _senal='Referencia cero (variación % no definida)'
        elif _dif>=20:
            _senal='Aumento frente a días comparables'
        elif _dif<=-20:
            _senal='Disminución frente a días comparables'
        else:
            _senal='Sin desviación de ±20 %'
        _rs.append({'Indicador':_label,'Día investigado':float(_v),
                    'Mediana comparable':_ref,'Variación %':_dif,
                    'Antecedentes':_n,'Señal':_senal})
    return pd.DataFrame(_rs,columns=_cols)


def _bi_valor_kpi(tabla, campo):
    if campo == 'IDE (kWh/km)':
        # El IDE de periodo es consumo tracción / kilometraje real.
        _km = _bi_serie(tabla,'Odómetro [km]').clip(lower=0).sum(min_count=1)
        _en = _bi_serie(tabla,'E_Tr').clip(lower=0).sum(min_count=1)
        return float(_en/_km) if pd.notna(_km) and _km > 0 and pd.notna(_en) else np.nan
    if campo not in tabla.columns:
        return np.nan
    _x = _bi_serie(tabla,campo)
    return float(_x.sum(min_count=1)) if _x.notna().any() else np.nan


def _bi_var_pct(actual, previo):
    if not np.isfinite(actual) or not np.isfinite(previo) or previo <= 0:
        return None
    return 100.0 * (actual - previo) / previo


def _bi_alertas_historicas(historico, visible, umbral_pct=30):
    """Alertas comparadas EXCLUSIVAMENTE con jornadas de la misma categoría.

    Mediana de hasta 45 antecedentes anteriores de igual tipo, con al menos 10
    observaciones positivas. La falta de energía con km se informa por separado.
    """
    _vacias=['Fecha','Tipo de jornada','Indicador','Hallazgo','Valor','Referencia','Variación %']
    if historico is None or visible is None or historico.empty or visible.empty:
        return pd.DataFrame(columns=_vacias)
    _cols = [c for c in ['E_Total','E_Tr','IDE (kWh/km)','Odómetro [km]', 'PAX','Servicios'] if c in historico]
    _grupos=['Tipo Día']+(['Etapa SFE'] if 'Etapa SFE' in historico else [])
    _hist = historico[['Fecha','Tipo de jornada']+_grupos+_cols].drop_duplicates('Fecha',keep='last').sort_values('Fecha').copy()
    _hist['_visible'] = _hist['Fecha'].isin(set(visible['Fecha'].dropna()))
    _registros=[]
    for _campo in ['E_Total', 'IDE (kWh/km)', 'Odómetro [km]', 'PAX', 'Servicios']:
        if _campo not in _hist:
            continue
        _v = pd.to_numeric(_hist[_campo], errors='coerce')
        # .shift() ANTES del rolling, agrupado por L, S o D/F. No filtra a futuro.
        _ref = _v.where(_v>0).groupby([_hist[c] for c in _grupos]).transform(
            lambda _serie: _serie.shift(1).rolling(45, min_periods=10).median())
        _desviacion=(_v/_ref-1)*100
        _ok = (_hist['_visible'] & _ref.gt(0) & _v.notna() &
               _desviacion.abs().ge(umbral_pct))
        for _i in np.flatnonzero(_ok.to_numpy()):
            _diff=float(_desviacion.iloc[_i])
            _registros.append({'Fecha':_hist['Fecha'].iloc[_i],
                               'Tipo de jornada':_hist['Tipo de jornada'].iloc[_i],
                               'Indicador':_campo,
                               'Hallazgo': 'Superior a referencia' if _diff>0 else 'Inferior a referencia',
                               'Valor':round(float(_v.iloc[_i]),2),
                               'Referencia':round(float(_ref.iloc[_i]),2),
                               'Variación %':round(_diff,1)})
    if 'E_Total' in _hist and 'Odómetro [km]' in _hist:
        _faltan=(_hist['_visible'] & _hist['Odómetro [km]'].gt(0) &
                 (_hist['E_Total'].isna() | _hist['E_Total'].le(0)))
        for _i in np.flatnonzero(_faltan.to_numpy()):
            _registros.append({'Fecha':_hist['Fecha'].iloc[_i],
                               'Tipo de jornada':_hist['Tipo de jornada'].iloc[_i],
                               'Indicador':'E_Total', 'Hallazgo':'Posible ausencia de dato de energía',
                               'Valor':float(_hist['E_Total'].iloc[_i]) if pd.notna(_hist['E_Total'].iloc[_i]) else np.nan,
                               'Referencia':np.nan,'Variación %':np.nan})
    if not _registros:
        return pd.DataFrame(columns=_vacias)
    return pd.DataFrame(_registros).sort_values(['Fecha','Indicador'],ascending=[False,True]).reset_index(drop=True)


def _bi_pronosticar(historico, indicador, dias=14):
    """Proyección por clases de jornada, incluyendo futuros festivos de Chile.

    Para una clase sin 10 antecedentes positivos se deja NaN (sin inventar datos
    ni sustituirlos por otra clase). La tendencia se calcula dentro de cada clase.
    """
    _vacias = ['Fecha', 'Tipo de jornada', 'Proyección', 'Indicador', 'Muestra de referencia']
    if historico is None or historico.empty or indicador not in historico.columns:
        return pd.DataFrame(columns=_vacias)
    _z=historico[['Fecha', indicador]].copy()
    _z['Fecha']=pd.to_datetime(_z['Fecha'],errors='coerce').dt.normalize()
    _z[indicador]=pd.to_numeric(_z[indicador],errors='coerce')
    _z=_z.dropna(subset=['Fecha']).sort_values('Fecha').drop_duplicates('Fecha',keep='last')
    if _z.empty:
        return pd.DataFrame(columns=_vacias)
    _ultima_fecha=_z['Fecha'].max()
    _z = _z[_z[indicador].gt(0)].copy()
    _z['Tipo Día'] = _z['Fecha'].dt.date.map(get_tipo_dia)
    _z['Etapa SFE'] = _z['Fecha'].map(_sfe_fase)
    _bases={}
    for _j in ('L','S','D/F'):
        _h=_z[(_z['Tipo Día']==_j) & (_z['Etapa SFE']==_sfe_fase(_ultima_fecha))].tail(90)
        _reciente=_h.tail(35)
        _n=len(_reciente)
        if _n<10:
            _bases[_j]=(np.nan,_n)
            continue
        _referencia=float(_reciente[indicador].median())
        # Tendencia por la misma jornada, nunca por promedio mezclado.
        if _n>=20:
            _a=float(_reciente[indicador].tail(10).median())
            _b=float(_reciente[indicador].iloc[-20:-10].median())
            _factor=float(np.clip(_a/_b,0.85,1.15)) if _b>0 else 1.0
        else:
            _factor=1.0
        _bases[_j]=(max(0.0,_referencia*_factor),_n)
    _fechas=pd.date_range(_ultima_fecha+pd.Timedelta(days=1),periods=int(dias),freq='D')
    _registros=[]
    for _f in _fechas:
        _tipo=get_tipo_dia(_f.date())
        _v,_n=(_bases.get(_tipo,(np.nan,0)) if _sfe_fase(_f)==_sfe_fase(_ultima_fecha)
               else (np.nan,0))
        _registros.append({'Fecha':_f, 'Tipo de jornada':_JORNADA_TXT.get(_tipo,'No determinado'),
                           'Proyección':_v,'Indicador':indicador,'Muestra de referencia':_n})
    return pd.DataFrame(_registros, columns=_vacias)


def _bi_calidad(historico, errores=None, duplicados_seat=None):
    """Controles descriptivos, sin modificar registros fuentes."""
    _incidencias=[]
    if historico.empty:
        return pd.DataFrame([{'Control':'Base operacional','Hallazgos':1,'Detalle':'Sin registros diarios disponibles'}])
    _fecha=pd.to_datetime(historico['Fecha'],errors='coerce')
    _mal=int(_fecha.isna().sum())
    _incidencias.append({'Control':'Fechas inválidas','Hallazgos':_mal,'Detalle':'Registros con fecha no interpretable'})
    _duplicadas=int(_fecha.duplicated(keep=False).sum())
    _incidencias.append({'Control':'Fechas repetidas','Hallazgos':_duplicadas,'Detalle':'Filas con igual fecha en la base diaria'})
    for _col in ['E_Total','E_Tr','Odómetro [km]','IDE (kWh/km)','PAX','Servicios']:
        if _col not in historico.columns:
            _incidencias.append({'Control':_col,'Hallazgos':len(historico),
                                  'Detalle':'Columna no disponible en la base histórica'})
            continue
        _serie=pd.to_numeric(historico[_col],errors='coerce')
        _vacios=int(_serie.isna().sum())
        _negativos=int((_serie<0).sum())
        _incidencias.append({'Control':_col,'Hallazgos':_vacios+_negativos,
                              'Detalle':f'{_vacios} sin valor; {_negativos} negativos'})
    _jornadas=historico['Fecha'].dt.date.map(get_tipo_dia)
    _no_clasificados=int((~_jornadas.isin(('L','S','D/F'))).sum())
    _incidencias.append({'Control':'Clasificación jornada (calendario Chile)',
                          'Hallazgos':_no_clasificados,
                          'Detalle':'L=laboral; S=sábado no festivo; D/F=domingo o festivo. Festivo prevalece.'})
    if 'Fuente' in historico.columns:
        _ausente=int(historico['Fuente'].astype(str).str.strip().str.upper().isin(['N/A','NONE','NAN','']).sum())
        _incidencias.append({'Control':'Fuente energética no disponible','Hallazgos':_ausente,
                              'Detalle':'Jornadas sin fuente de energía asignada'})
    if duplicados_seat is not None:
        _incidencias.append({'Control':'SEAT · duplicados resueltos','Hallazgos':int(duplicados_seat),
                              'Detalle':'Registros excluidos por regla de prioridad existente'})
    if errores:
        _incidencias.append({'Control':'Archivos con error de procesamiento','Hallazgos':len(errores),
                              'Detalle':'Consultar detalle de excepciones de carga'})
    return pd.DataFrame(_incidencias)



